params.script_inline:
# file-space/derive -- what a file knows about itself (GH #903).
#
# Two jobs, one cell, because both need the same three things -- the text
# view of a version, the embedder and the summarizer -- and this is the ONLY
# cell of the hive that wakes a model or the network (`read`, `write`, `ws`,
# `guard` never do):
#
#   in_derive {file, version}   from `./write` (and `./ws` on a commit) after
#       every head move of the main line: text view -> sections -> one
#       embedding per section -> the one-line and the short summary -> rows in
#       `summaries`/`embeddings`, `files.oneline`. Working versions never get
#       here, and a version that is not on the main line is dropped. Before
#       any model is asked, the head's nodes and links (the pure extractor
#       block below) replace the file's rows in `nodes`/`links`/`node_runs`,
#       and ONE `source_changed` leaves the hive (GH #944, README "Nodes and
#       links") -- whatever the summary or the embedding does afterwards.
#       The summary brings the file's topic tags along (`TAGS:`, GH #947);
#       once it is stored and the version is still the living head, ONE
#       `source_described` leaves the hive with the one line and the tags.
#   in_read op `search` mode `semantic`, op `ask`: the question is embedded,
#       `similar` ranks the sections of THIS file and THIS version only, and
#       `ask` hands the best sections -- never the whole file -- to the
#       summarizer with a fixed brief.
#   in_dirs {file} from `./write` (after a remove or a move) and `./ws` (a
#       file a commit removed), and the end of every derive job: the sync job
#       (GH #947) moves the file's contribution -- path, head, bytes, nodes,
#       file vector, tags -- into the `dirs` rows of every ancestor, as the
#       difference to the one `contrib` last counted in. Silent: no answer, no
#       event.
#   in_read op `dir_summary`: the one line of a directory, made by the
#       summarizer only when the directory changed since the last one (lazy,
#       never cascading, never started by a write).
#
# Every store call on a table of files carries `file` in its `where` (R-FH-1,
# second condition): a hit of file X can never come out of file Y, even when
# both hold the same block (`dirs` is a table of directories, read by path). Working values between phases live in `pending` rows of this cell
# (dev-rules 8c), never in the context: the context carries the job id alone
# (`cur_job`, lifted by the edges), because the context is no stack.
#
# `sections(text, kind)` and the other helpers above the program are PURE:
# the locks load them via `ast` without running the per-message program.
import sys, json, re, base64, hashlib, secrets, datetime, ast

ME = "derive"
ONELINE_MAX = 120
SHORT_MAX = 1200
SECTION_LINES = 60
SECTION_OVERLAP = 10
MAX_SECTIONS = 400
EMBED_MAX_CHARS = 8000
SUMMARY_INPUT_MAX = 48000
ASK_SECTIONS = 4
ASK_EXACT_CONTEXT = 2
SEARCH_LIMIT = 20
PREVIEW_LINES = 3
BLOCK_FETCH = 4096
PAGE_FETCH = 1000
PAGE_HEAD = re.compile(r"^--- page (\d+) ---$")
MD_HEAD = re.compile(r"^(#{1,6})\s+(.*?)\s*#*\s*$")
FENCE = re.compile(r"^\s*(```|~~~)")
MD_EXT = (".md", ".markdown", ".mdx")
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
ID_RE = re.compile(r"^fh-[0-9a-f]{12}$")
HEX_RE = re.compile(r"^[0-9a-f]{4,64}$")
NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,64}$")
SYNC_READS = 3
SYNC_TRIES = 3
AGG_RETRIES = 8
DIR_SUMMARY_CHILDREN = 50
DIR_COLS = ["path", "files", "bytes", "nodes", "vec_counts", "vec_n", "tags", "dirty",
            "summary", "summary_seq", "changed_seq", "tomb"]
CONTRIB_COLS = ["file", "path", "version", "bytes", "nodes", "vec", "tags", "seq"]
SUMMARY_PROMPT = (
    "Summarize the file below for someone deciding whether to open it. Answer in "
    "exactly this form: the first line is ONE sentence of at most 120 characters "
    "that says what the file is and what it is for; then one empty line; then one "
    "plain paragraph of at most 1200 characters on what it contains; then one empty "
    "line; then, as the very last line, `TAGS: ` followed by at most 8 short topic "
    "words of the file, lower case, separated by commas. No headings, no lists, no "
    "quotes of the whole file, nothing that is not in the file.")
DIR_SUMMARY_PROMPT = (
    "Summarize the directory below for someone deciding whether to look inside. "
    "Its entries are listed with their own one-line summaries (a sub-directory "
    "ends in `/`). Answer with ONE sentence of at most 120 characters that says "
    "what the directory holds and what it is for. Nothing that is not in the "
    "entries, no list of names.")
ASK_PROMPT = (
    "Answer only from these lines; cite line ranges. The lines below are numbered "
    "parts of one file, nothing else is known about it. If they do not hold the "
    "answer, say so in one sentence. End with one line of the form "
    "`SOURCES: <from>-<to>, <from>-<to>` naming the ranges you used.")


# ------------------------------------------------------------------ pure part

# ------------------------------------------------------------ the twins
# `parse_addr`, `line_hash` and `text_view` are word for word the copies in
# `./read` (`script_inline` has no library); the lock
# `gh899_the_twins_parse_one_address` runs every copy against one table, so
# an address, a line hash and a text view mean the same here as in `read`.

def parse_addr(s):
    """An address -> {file, path, at, ref, anchor}; `at` is `head`, `v`
    (`ref` a hex prefix), `ws` or `snap` (`ref` a name). A malformed address
    is {error: 'bad_address'}. An anchor (`#...`) is parsed, never resolved."""
    if not isinstance(s, str) or not s.strip() or len(s) > 1024:
        return {"error": "bad_address"}
    s = s.strip()
    anchor = ""
    if "#" in s:
        s, anchor = s.split("#", 1)
        if not anchor:
            return {"error": "bad_address"}
    at, ref = "head", ""
    if "@" in s:
        base, suffix = s.rsplit("@", 1)
        if suffix.startswith("ws:") or suffix.startswith("snap:"):
            kind, name = suffix.split(":", 1)
            if not NAME_RE.match(name):
                return {"error": "bad_address"}
            at, ref, s = kind, name, base
        elif HEX_RE.match(suffix):
            at, ref, s = "v", suffix, base
        elif ID_RE.match(base):
            return {"error": "bad_address"}
    if ID_RE.match(s):
        return {"file": s, "path": "", "at": at, "ref": ref, "anchor": anchor}
    if s.startswith("/") and "\x00" not in s and "//" not in s and len(s) > 1 \
            and not s.endswith("/"):
        return {"file": "", "path": s, "at": at, "ref": ref, "anchor": anchor}
    return {"error": "bad_address"}


def line_hash(line):
    """`h4`: the first four hex digits of the sha256 of one line without its
    line ending (`\\n`, `\\r\\n`)."""
    if line.endswith("\n"):
        line = line[:-1]
    if line.endswith("\r"):
        line = line[:-1]
    return hashlib.sha256(line.encode("utf-8")).hexdigest()[:4]


def text_view(content, derived):
    """The text a version reads as: its derived pages (`[{part, text}]`),
    each headed `--- page <n> ---`, when it has any, else its own lines when
    the content is UTF-8 without NUL. Pages first: an extractor made them
    because the bytes are not the text, and a PDF can be pure ASCII
    (GH #907, OR-FJ.I.22). {kind, lines, pages: {n: [from, to]}} (1-based,
    inclusive) or {error: 'no_text'}. A line keeps a `\\r` of its ending;
    `\\n` ends a line, a last line without one counts."""
    def split(t):
        if t == "":
            return []
        parts = t.split("\n")
        if t.endswith("\n"):
            parts = parts[:-1]
        return parts

    parts = sorted((p for p in (derived or []) if isinstance(p, dict)),
                   key=lambda p: int(p.get("part") or 0))
    text = None
    if not parts and isinstance(content, (bytes, bytearray)) and b"\x00" not in content:
        try:
            text = bytes(content).decode("utf-8")
        except UnicodeDecodeError:
            text = None
    if text is not None:
        return {"kind": "text", "lines": split(text), "pages": {}}
    if not parts:
        return {"error": "no_text"}
    lines, pages = [], {}
    for p in parts:
        n = int(p.get("part") or 0)
        start = len(lines) + 1
        lines.append("--- page %d ---" % n)
        lines.extend(split(str(p.get("text") or "")))
        pages[n] = [start, len(lines)]
    return {"kind": "derived", "lines": lines, "pages": pages}


# ---- directories (GH #947) -- word for word in ./write, ./derive and ./read
# A directory is a path without a trailing slash ("/" is the root): the
# directory of a file is everything before its last "/", and its ancestors
# are every prefix up to it, root first. The lock
# `gh947_the_directory_twins_are_one` runs every copy against one table.
TAGS_MAX = 8
TAG_CHARS = 32


def dir_of(path):
    """The directory a path lives in: '/a/b/x.py' -> '/a/b', '/x' -> '/'."""
    p = str(path or "").rstrip("/")
    i = p.rfind("/")
    return p[:i] if i > 0 else "/"


def dir_norm(path):
    """A directory as the rows name it: '/a/b/' -> '/a/b', '' -> '/'."""
    return "/" + "/".join(s for s in str(path or "").split("/") if s)


def ancestors(d):
    """'/a/b' -> ['/', '/a', '/a/b'] (root first); '/' -> ['/']."""
    segs = [s for s in str(d or "").split("/") if s]
    return ["/"] + ["/" + "/".join(segs[:i]) for i in range(1, len(segs) + 1)]


def dir_parent(d):
    """The parent of a directory; '' for the root."""
    d = dir_norm(d)
    return "" if d == "/" else dir_of(d)


def dir_depth(d):
    """Segments below the root: '/' -> 0, '/a/b' -> 2."""
    return len([s for s in str(d or "").split("/") if s])


def tags_norm(v):
    """A tag list as it is stored: strings, lower case, inner whitespace
    folded, cut to TAG_CHARS, no empty one, no repeat, at most TAGS_MAX (the
    first ones win). A JSON string of a list is read too; anything else is []."""
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except Exception:
            return []
    if not isinstance(v, list):
        return []
    out = []
    for t in v:
        if not isinstance(t, str):
            continue
        t = " ".join(t.lower().split()).strip(" .;:")[:TAG_CHARS].rstrip()
        if t and t not in out:
            out.append(t)
        if len(out) == TAGS_MAX:
            break
    return out
# ---- directories end


# ---- aggregation (GH #947): the contribution of one file and its delta
# Stage 1 (files, bytes, nodes) and stage 2 (bit counters of the file
# vectors, topic counters of the tags) of every directory above a file are
# sums of the files' contributions. A contribution is what the store says of
# the file NOW -- path, head, bytes, the head's node count and file vector,
# the head's tags -- and `contrib` holds the one last counted in. Moving the
# directories is the difference of the two on every ancestor of the old and
# the new path, never a read of a sibling.


def vec_bits(b64):
    """The sign bits of a file vector (base64, `node_runs.fvec`) as 0/1 ints;
    [] for none or an unreadable one."""
    try:
        raw = base64.b64decode(str(b64 or ""), validate=True)
    except Exception:
        return []
    return [(byte >> (7 - k)) & 1 for byte in raw for k in range(8)]


def contrib_of(file, path, version, size, nodes, vec, tags):
    """A contribution in the one form `agg_delta` compares."""
    return {"file": str(file), "path": str(path), "version": str(version or ""),
            "bytes": int(size or 0), "nodes": int(nodes or 0), "vec": str(vec or ""),
            "tags": tags_norm(tags)}


def contrib_row(r):
    """A `contrib` row read back (tags are a JSON string there), or None."""
    if not r:
        return None
    return contrib_of(r.get("file"), r.get("path"), r.get("version"), r.get("bytes"),
                      r.get("nodes"), r.get("vec"), r.get("tags"))


def agg_delta(old, new):
    """{dir: {files, bytes, nodes, vec, vec_n, tags}} for every ancestor of
    `old` and `new` (contributions or None). Equal contributions give {}; any
    other change -- a new version with the same counts too -- names every
    ancestor of both paths, because each of them is dirty from now on."""
    if old == new:
        return {}
    out = {}

    def add(c, sign):
        bits = vec_bits(c["vec"])
        for p in ancestors(dir_of(c["path"])):
            e = out.setdefault(p, {"files": 0, "bytes": 0, "nodes": 0, "vec": [],
                                   "vec_n": 0, "tags": {}})
            e["files"] += sign
            e["bytes"] += sign * c["bytes"]
            e["nodes"] += sign * c["nodes"]
            if bits:
                e["vec_n"] += sign
                if len(e["vec"]) < len(bits):
                    e["vec"] += [0] * (len(bits) - len(e["vec"]))
                for i, b in enumerate(bits):
                    e["vec"][i] += sign * b
            for t in c["tags"]:
                e["tags"][t] = e["tags"].get(t, 0) + sign
                if not e["tags"][t]:
                    del e["tags"][t]
    if old:
        add(old, -1)
    if new:
        add(new, 1)
    return out


def agg_apply(row, delta):
    """The counter columns of a `dirs` row after `delta`: stored values plus
    the delta, never below zero (a counter below zero is drift, and a sum of
    contributions never is); vectors of another width are padded."""
    row = row or {}

    def num(k):
        try:
            return int(row.get(k) or 0)
        except (TypeError, ValueError):
            return 0

    try:
        counts = [int(x) for x in json.loads(str(row.get("vec_counts") or "[]"))]
    except Exception:
        counts = []
    dv = list(delta.get("vec") or [])
    width = max(len(counts), len(dv))
    counts += [0] * (width - len(counts))
    dv += [0] * (width - len(dv))
    counts = [max(0, a + b) for a, b in zip(counts, dv)]
    try:
        tags = json.loads(str(row.get("tags") or "{}"))
        tags = {str(k): int(v) for k, v in tags.items()} if isinstance(tags, dict) else {}
    except Exception:
        tags = {}
    for t, n in (delta.get("tags") or {}).items():
        tags[t] = tags.get(t, 0) + n
        if tags[t] <= 0:
            del tags[t]
    vec_n = max(0, num("vec_n") + int(delta.get("vec_n") or 0))
    if not vec_n:
        counts = []
    return {"files": max(0, num("files") + int(delta.get("files") or 0)),
            "bytes": max(0, num("bytes") + int(delta.get("bytes") or 0)),
            "nodes": max(0, num("nodes") + int(delta.get("nodes") or 0)),
            "vec_counts": json.dumps(counts), "vec_n": vec_n,
            "tags": json.dumps(tags, sort_keys=True)}
# ---- aggregation end


# ------------------------------------------------------------ pure part

def read_form(n, line):
    """One line in the read form `n:h4|text` -- `read`'s `fmt_line`: a
    line's `\\r` is not shown and not hashed, so the `h4` of a hit is the one
    `read` shows and `replace_lines` checks."""
    if line.endswith("\r"):
        line = line[:-1]
    return "%d:%s|%s" % (n, line_hash(line), line)


def split_lines(text):
    """Lines of a text view; a final line end opens no extra empty line."""
    if not text:
        return []
    lines = text.split("\n")
    if text.endswith("\n"):
        lines.pop()
    return lines


def kind_of(path, mime):
    p = str(path or "").lower()
    m = str(mime or "").lower()
    if p.endswith(MD_EXT) or m == "text/markdown":
        return "markdown"
    return "text"


def _units(lines, kind):
    """The hard spans a section never crosses: pages of a text view, headings
    of Markdown, the whole text otherwise. (from_line, to_line, name), 1-based."""
    n = len(lines)
    heads = []
    if kind == "pages":
        heads = [(i + 1, "page " + PAGE_HEAD.match(l).group(1))
                 for i, l in enumerate(lines) if PAGE_HEAD.match(l)]
    elif kind == "markdown":
        fenced = False
        for i, l in enumerate(lines):
            if FENCE.match(l):
                fenced = not fenced
                continue
            m = None if fenced else MD_HEAD.match(l)
            if m and m.group(2):
                heads.append((i + 1, m.group(2)))
    if not heads:
        return [(1, n, "")]
    out = []
    if heads[0][0] > 1:
        out.append((1, heads[0][0] - 1, ""))
    for k, (a, name) in enumerate(heads):
        b = heads[k + 1][0] - 1 if k + 1 < len(heads) else n
        out.append((a, b, name))
    return out


def _windows(a, b, w, o):
    if b - a + 1 <= w:
        return [(a, b)]
    out, start = [], a
    while True:
        end = min(start + w - 1, b)
        out.append((start, end))
        if end == b:
            return out
        start = end - o + 1


def sections(text, kind, window=None, overlap=None, cap=None):
    """Cut a text view into the sections that are embedded one by one.

    Markdown at its headings (not inside fenced code), a text view of pages at
    its `--- page <n> ---` lines, anything else as one span; a span longer than
    `window` lines is cut into windows of `window` lines overlapping by
    `overlap`. Pages and headings are hard borders -- no section crosses one.
    At most `cap` sections: above it the windows grow (double, again and
    again) and, when the borders alone are too many, neighbouring spans are
    joined -- still only at a border. Returns [{section, from_line, to_line,
    text}] in text order; `section` is the heading, the page, or "lines a-b"."""
    window = int(window or SECTION_LINES)
    overlap = int(SECTION_OVERLAP if overlap is None else overlap)
    cap = int(cap or MAX_SECTIONS)
    overlap = max(0, min(overlap, window - 1))
    lines = split_lines(text)
    if not lines:
        return []
    units = _units(lines, kind)
    if len(units) > cap:
        k = -(-len(units) // cap)
        units = [(units[i][0], units[min(i + k, len(units)) - 1][1], units[i][2])
                 for i in range(0, len(units), k)]
    w, o = window, overlap
    while True:
        spans = [(a, b, name) for (ua, ub, name) in units
                 for (a, b) in _windows(ua, ub, w, o)]
        if len(spans) <= cap:
            break
        w, o = w * 2, o * 2
    return [{"section": name or ("lines %d-%d" % (a, b)), "from_line": a,
             "to_line": b, "text": "\n".join(lines[a - 1:b])}
            for (a, b, name) in spans]


def assemble_blocks(hashes, blocks_rows):
    """The bytes of a version from its block list and the `blocks` rows the
    store returned ({hash, enc, body}); None when a block is missing or its
    base64 is broken -- a broken version is never read around. The bytes are
    joined before anything decodes them, so a block cut inside a character
    does not make a text file binary."""
    have = {}
    for r in blocks_rows or []:
        if isinstance(r, dict):
            have[str(r.get("hash") or "")] = r
    parts = []
    for h in hashes:
        r = have.get(str(h))
        if r is None:
            return None
        body = str(r.get("body") or "")
        if str(r.get("enc") or "utf8") == "b64":
            try:
                parts.append(base64.b64decode(body, validate=True))
            except Exception:
                return None
        else:
            parts.append(body.encode("utf-8"))
    return b"".join(parts)


def view_text(content, pages):
    """(text, paged) of a version through the twin `text_view`: `pages` are
    its `derived` rows ({part, body}); the lines come back joined, each ended
    by `\\n`, so `split_lines` gives the twin's lines back one for one (the
    line numbers of a section are `read`'s). (None, False) = no text view."""
    if content is None:
        return None, False
    tv = text_view(content, [{"part": p.get("part"), "text": p.get("body")}
                             for p in pages or [] if isinstance(p, dict)])
    if "error" in tv:
        return None, False
    lines = tv["lines"]
    return ("\n".join(lines) + "\n" if lines else ""), tv["kind"] == "derived"


def block_hashes(raw):
    """`versions.blocks` as a list of hashes (plain strings or {hash})."""
    try:
        v = json.loads(raw) if isinstance(raw, str) else raw
    except Exception:
        return None
    if not isinstance(v, list):
        return None
    out = []
    for x in v:
        h = x.get("hash") if isinstance(x, dict) else x
        if not isinstance(h, str) or not h:
            return None
        out.append(h)
    return out


def basename(path):
    p = str(path or "").rstrip("/")
    return p.rsplit("/", 1)[-1] or p or "file"


def name_oneline(path, mime, kind, size):
    """The one line of a file without a text view -- no model: name and type."""
    what = str(mime or "") or str(kind or "") or "binary"
    return ("%s: %s, %s bytes" % (basename(path), what, int(size or 0)))[:ONELINE_MAX]


def summary_input(path, text, secs):
    head = "Path: %s\n\n" % path
    if len(text) <= SUMMARY_INPUT_MAX:
        return head + text
    cut = text[:SUMMARY_INPUT_MAX]
    rest = [s["section"] for s in secs if s["from_line"] > cut.count("\n") + 1]
    tail = "\n[... cut after %d characters" % SUMMARY_INPUT_MAX
    if rest:
        tail += "; sections of the rest: " + "; ".join(rest[:60])
    return head + cut + tail + "]"


def parse_summary(text):
    """The summarizer's answer as (oneline, short, tags), or None when it is
    empty. Every line that starts with `TAGS:` (any case, wherever it
    stands) is taken out first and its rest, split at commas, is the tag list
    (`tags_norm`; none -> []), GH #947. Of the other lines the first non-empty
    one is the one line, the rest the short summary (the one line again when
    the model gave nothing more); both cut to their cap."""
    lines, raw = [], []
    for l in str(text or "").strip().split("\n"):
        l = l.strip()
        if l[:5].upper() == "TAGS:":
            raw += [t.strip(" .;:`'\"") for t in l[5:].split(",")]
        else:
            lines.append(l)
    first = next((i for i, l in enumerate(lines) if l), None)
    if first is None:
        return None
    one = lines[first].strip("# ").strip()
    rest = " ".join(l for l in lines[first + 1:] if l).strip()
    one = one[:ONELINE_MAX].rstrip()
    short = (rest or one)[:SHORT_MAX].rstrip()
    return (one, short, tags_norm(raw)) if one else None


def exact_hit(question, lines, covered):
    """The one line holding most of the question's words (>= 4 letters,
    case-folded), when no chosen section already covers it: (from, to) with
    ASK_EXACT_CONTEXT lines around it, else None."""
    words = {w for w in re.findall(r"\w+", str(question or "").lower()) if len(w) >= 4}
    if not words:
        return None
    best, best_n = 0, 0
    for i, l in enumerate(lines):
        low = l.lower()
        n = sum(1 for w in words if w in low)
        if n > best_n:
            best, best_n = i + 1, n
    if not best_n or any(a <= best <= b for a, b in covered):
        return None
    return (max(1, best - ASK_EXACT_CONTEXT), min(len(lines), best + ASK_EXACT_CONTEXT))


def ask_input(path, v12, summary, chunks, lines, question):
    out = ["File: %s (version %s)" % (path, v12)]
    if summary:
        out.append("Summary: " + summary)
    for a, b in chunks:
        out.append("")
        out.append("Lines %d-%d:" % (a, b))
        out.extend("%d: %s" % (n, lines[n - 1]) for n in range(a, b + 1))
    out.append("")
    out.append("Question: " + question)
    return "\n".join(out)


def parse_sources(answer, chunks):
    """(answer text, sources) from the model's reply: the `SOURCES:` line names
    the ranges; only ranges that touch a chunk it was given count, and a reply
    that names none cites every chunk it got."""
    named, keep = [], []
    for l in str(answer or "").strip().split("\n"):
        if l.strip().upper().startswith("SOURCES:"):
            for a, b, one in re.findall(r"(\d+)\s*[-\u2013]\s*(\d+)|(\d+)", l.split(":", 1)[1]):
                named.append((int(a or one), int(b or one)))
        else:
            keep.append(l)
    srcs = [(a, b) for a, b in named if a <= b and any(a <= cb and b >= ca for ca, cb in chunks)]
    out = []
    for a, b in srcs or list(chunks):
        if {"from_line": a, "to_line": b} not in out:
            out.append({"from_line": a, "to_line": b})
    return "\n".join(keep).strip(), out


def score(distance, dim):
    bits = max(1, int(dim or 0))
    return round(max(0.0, 1.0 - float(distance or 0) / bits), 4)


# ---- extractors begin (twin of ./derive and ./read; GH #944)
# The nodes and the outgoing links of a file: what a file is made of (classes,
# functions, sections, keys, pages) under anchors that survive an edit which
# only moves lines, and what it points at (imports, uses, links). `./derive`
# runs it on every head; `./read` runs it on a version that is not the head
# (an older one, a workspace), so the two copies are word for word the same
# block -- the lock `gh944_two_extractors_give_the_same_anchors` holds them
# byte for byte, like the address twins above.
#
# Standard library only (R-BC-1): a cell has no packages, and every format
# goes through ONE register, `EXTRACTORS = {fmt: [extractor, ...]}`, the
# order being the fallback chain. An extractor is `(data, pages) -> {nodes,
# links, parser}` or a built-in exception ("not readable"); a later tree-sitter
# extractor swaps one register entry and touches nothing else. Links are only
# what the syntax says (imports, `use`, written links), never a guess from a
# name. Everything here is pure: no I/O, no params, bounded loops only.

EX_DEFAULTS = {"nodes_max": 2000, "links_max": 5000, "extract_max_bytes": 2097152, "key_depth": 3}
EX_ONELINE = 120
EX_KEY_DEPTH_CAP = 32
EX_EXT = {".py": "python", ".rs": "rust", ".md": "markdown", ".markdown": "markdown",
          ".json": "json", ".toml": "toml", ".pdf": "pdf"}
EX_PY_ITEM = re.compile(r"[ \t\f]*(?:async[ \t]+)?(def|class)[ \t]+([^\W\d]\w*)")
EX_MD_FENCE = re.compile(r"^ {0,3}(`{3,}|~{3,})(.*)$")
EX_MD_HEAD = re.compile(r"^ {0,3}(#{1,6})(?:[ \t]+(.*?))?[ \t]*$")
EX_MD_CODE = re.compile(r"(`+)(.+?)\1")
EX_MD_REFDEF = re.compile(r"^ {0,3}\[[^\]]+\]:[ \t]*(<[^>]*>|\S+)")
EX_MD_INLINE = re.compile(r"\]\([ \t]*(<[^>]*>|[^)\s]+)(?:[ \t]+(?:\"[^\"]*\"|'[^']*'|\([^)]*\)))?[ \t]*\)")
EX_MD_AUTO = re.compile(r"<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s<>]*)>")
EX_MD_BARE = re.compile(r"(?<![\w/(<])https?://[^\s<>()\[\]]+")
EX_SCHEME = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")
EX_TOML_BARE = re.compile(r"[A-Za-z0-9_-]+")


def format_of(path, mime):
    """The format of a file by its name (case-insensitive), a PDF also by its
    type; None when no extractor reads it (a binary without a name, YAML...)."""
    name = str(path or "").rsplit("/", 1)[-1].lower()
    dot = name.rfind(".")
    fmt = EX_EXT.get(name[dot:]) if dot > 0 else None
    if fmt is None and str(mime or "").split(";")[0].strip().lower() == "application/pdf":
        fmt = "pdf"
    return fmt


def anchor_part(art, name):
    """`<art>:<name>`; `%`, `#`, `@` and whitespace in the name are %XX, so an
    anchor never breaks the address `fh-..@v#anchor` it rides in."""
    out = []
    for ch in str(name):
        if ch in "%#@" or ch.isspace():
            out.append("".join("%%%02X" % b for b in ch.encode("utf-8")))
        else:
            out.append(ch)
    return "%s:%s" % (art, "".join(out))


def anchor_of(segments):
    return "/".join(anchor_part(a, n) for a, n in segments)


def unique_anchor(seen, anchor):
    """The second item with the same anchor in one file is `anchor~2`, the
    third `~3`, in source order: an anchor names one item, never two."""
    n = seen.get(anchor, 0) + 1
    seen[anchor] = n
    return anchor if n == 1 else "%s~%d" % (anchor, n)


def md_slug(text):
    """GitHub's heading slug: lower case, punctuation but `-`/`_` dropped,
    every whitespace a `-`."""
    s = re.sub(r"[^\w\s-]", "", str(text).strip().lower())
    return re.sub(r"\s", "-", s)


def resolve_link(path, target):
    """A written relative link as the absolute space path it points at; `..`
    folded, `#frag` kept; a bare `#frag` is this file. None above the root:
    a link that leaves the space is no edge."""
    target = str(target)
    if target.startswith("#"):
        return str(path) + target
    t, sep, frag = target.partition("#")
    parts = [] if t.startswith("/") else [p for p in str(path).split("/") if p][:-1]
    for seg in t.split("/"):
        if seg in ("", "."):
            continue
        if seg == "..":
            if not parts:
                return None
            parts.pop()
        else:
            parts.append(seg)
    return "/" + "/".join(parts) + ("#" + frag if sep else "")


def _ex_text(data):
    return bytes(data or b"").decode("utf-8-sig")


def _ex_join(parent, part):
    return part if not parent else parent + "/" + part


def _ex_node(ctx, kind, parent, part, frm, to, unit="line", oneline=None):
    # A key's pointer already names its whole path: it is one segment, its
    # parent only a field. Every other item nests under its parent's anchor.
    anchor = unique_anchor(ctx["seen"], part if kind == "key" else _ex_join(parent, part))
    if oneline is None:
        lines = ctx["lines"]
        oneline = lines[frm - 1] if 0 < frm <= len(lines) else ""
    ctx["nodes"].append({"anchor": anchor, "kind": kind, "parent": parent or "", "unit": unit,
                         "from": frm, "to": to, "oneline": str(oneline).strip()[:EX_ONELINE]})
    return anchor


def _ex_ctx(text):
    return {"lines": text.split("\n"), "seen": {}, "nodes": [], "links": []}


def _ex_link(ctx, kind, from_anchor, target, pos, alias=None):
    link = {"kind": kind, "from_anchor": from_anchor or "", "target_name": target, "pos": pos}
    # `alias` is only what the syntax binds with `as` (python imports): a
    # link without one has no key at all, so the plain form stays the plain
    # form and an empty alias never reads as a name.
    if alias:
        link["alias"] = alias
    ctx["links"].append(link)


# ---- python: `ast` first, the indentation scanner when `ast` cannot read it

def _ex_dotted(e):
    if isinstance(e, ast.Name):
        return e.id
    if isinstance(e, ast.Attribute):
        head = _ex_dotted(e.value)
        return None if head is None else head + "." + e.attr
    return None


def _ex_py_walk(node, parent, ctx, mods):
    for ch in ast.iter_child_nodes(node):
        if isinstance(ch, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            kind = "class" if isinstance(ch, ast.ClassDef) else "def"
            anchor = _ex_node(ctx, kind, parent, anchor_part(kind, ch.name),
                              ch.lineno, getattr(ch, "end_lineno", None) or ch.lineno)
            _ex_py_walk(ch, anchor, ctx, mods)
            continue
        if isinstance(ch, ast.Import):
            for a in ch.names:
                _ex_link(ctx, "import", parent, a.name, ch.lineno, a.asname)
        elif isinstance(ch, ast.ImportFrom):
            base = "." * (ch.level or 0) + (ch.module or "")
            for a in ch.names:
                _ex_link(ctx, "import", parent, base + ":" + a.name, ch.lineno, a.asname)
        elif isinstance(ch, ast.Call):
            f = ch.func
            if isinstance(f, ast.Name):
                _ex_link(ctx, "call", parent, f.id, ch.lineno)
            elif isinstance(f, ast.Attribute):
                # Only a module bound by `import` is a callee we know; any
                # other `obj.meth()` would be a guess about `obj`.
                owner = _ex_dotted(f.value)
                if owner is not None and owner in mods:
                    _ex_link(ctx, "call", parent, mods[owner] + ":" + f.attr, ch.lineno)
        _ex_py_walk(ch, parent, ctx, mods)


def extract_python_ast(data, pages):
    text = _ex_text(data)
    tree = ast.parse(text)
    mods = {}
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            for a in n.names:
                if a.asname:
                    mods[a.asname] = a.name
                else:
                    parts = a.name.split(".")
                    for k in range(1, len(parts) + 1):
                        mods[".".join(parts[:k])] = ".".join(parts[:k])
    ctx = _ex_ctx(text)
    _ex_py_walk(tree, "", ctx, mods)
    ctx["links"].sort(key=lambda l: l["pos"])
    return {"nodes": ctx["nodes"], "links": ctx["links"], "parser": "ast"}


def _ex_py_blank(text):
    """The text with comments dropped and string contents blanked (quotes and
    line ends stay), and for every line whether it starts a logical line --
    not inside brackets, a string or after a backslash. A line opening with
    `def`/`class` closes any bracket left open: no expression holds those
    keywords, and one unclosed bracket must not swallow the rest of a file
    that `ast` already refused."""
    out, starts = [], []
    depth, cont, start, i, n = 0, False, True, 0, len(text)
    while i < n:
        if start:
            if depth and EX_PY_ITEM.match(text, i):
                depth = 0
            starts.append(depth == 0 and not cont)
            start, cont = False, False
        c = text[i]
        if c == "#":
            j = text.find("\n", i)
            i = n if j < 0 else j
            continue
        if c in "\"'":
            q = c * 3 if text.startswith(c * 3, i) else c
            j = i + len(q)
            done = False
            while j < n:
                if text[j] == "\\":
                    j += 2
                    continue
                if text.startswith(q, j):
                    done = True
                    break
                if len(q) == 1 and text[j] == "\n":
                    break
                j += 1
            out.append(q)
            for ch in text[i + len(q):min(j, n)]:
                if ch == "\n":
                    out.append("\n")
                    starts.append(False)
                else:
                    out.append(" ")
            if done:
                out.append(q)
                j += len(q)
            i = j
            continue
        if c == "\\" and text.startswith("\n", i + 1):
            cont = True
            out.append(" ")
            i += 1
            continue
        if c in "([{":
            depth += 1
        elif c in ")]}":
            depth = max(0, depth - 1)
        elif c == "\n":
            start = True
        out.append(c)
        i += 1
    lines = "".join(out).split("\n")
    starts += [False] * (len(lines) - len(starts))
    return lines, starts


def extract_python_scan(data, pages):
    text = _ex_text(data)
    ctx = _ex_ctx(text)
    blank, starts = _ex_py_blank(text)
    stack, last = [], 0
    for ln, (line, first) in enumerate(zip(blank, starts), 1):
        if not line.strip():
            continue
        if first:
            ind = len(line.expandtabs(8)) - len(line.expandtabs(8).lstrip())
            while stack and stack[-1][0] >= ind:
                ctx["nodes"][stack.pop()[1]]["to"] = last
            m = EX_PY_ITEM.match(line)
            if m:
                kind = m.group(1)
                anchor = _ex_node(ctx, kind, stack[-1][2] if stack else "",
                                  anchor_part(kind, m.group(2)), ln, ln)
                stack.append((ind, len(ctx["nodes"]) - 1, anchor))
        last = ln
    while stack:
        ctx["nodes"][stack.pop()[1]]["to"] = last
    return {"nodes": ctx["nodes"], "links": [], "parser": "scan"}


# ---- rust: a token scanner (strings, raw strings, chars, nested comments)

def _ex_rs_tokens(text):
    toks, i, n, line = [], 0, len(text), 1
    while i < n:
        c = text[i]
        if c == "\n":
            line += 1
            i += 1
            continue
        if c.isspace():
            i += 1
            continue
        if text.startswith("//", i):
            j = text.find("\n", i)
            i = n if j < 0 else j
            continue
        if text.startswith("/*", i):
            depth, j = 1, i + 2
            while depth:
                if j >= n:
                    raise ValueError("unterminated block comment")
                if text.startswith("/*", j):
                    depth, j = depth + 1, j + 2
                elif text.startswith("*/", j):
                    depth, j = depth - 1, j + 2
                else:
                    j += 1
            line += text.count("\n", i, j)
            i = j
            continue
        if c == "_" or c.isalpha():
            j = i + 1
            while j < n and (text[j] == "_" or text[j].isalnum()):
                j += 1
            w = text[i:j]
            if w in ("r", "br", "cr") and j < n and text[j] in "\"#":
                k = j
                while k < n and text[k] == "#":
                    k += 1
                if k < n and text[k] == "\"":
                    close = "\"" + "#" * (k - j)
                    e = text.find(close, k + 1)
                    if e < 0:
                        raise ValueError("unterminated raw string")
                    toks.append(("\"", "str", line))
                    line += text.count("\n", i, e)
                    i = e + len(close)
                    continue
                if w == "r" and k == j + 1 and k < n and (text[k] == "_" or text[k].isalpha()):
                    m = k + 1
                    while m < n and (text[m] == "_" or text[m].isalnum()):
                        m += 1
                    toks.append((text[k:m], "rid", line))
                    i = m
                    continue
            if w in ("b", "c") and j < n and text[j] == "\"" or w == "b" and j < n and text[j] == "'":
                i = j
                continue
            toks.append((w, "id", line))
            i = j
            continue
        if c.isdigit():
            j = i + 1
            while j < n and (text[j] == "_" or text[j].isalnum()
                             or text[j] == "." and j + 1 < n and text[j + 1].isdigit()):
                j += 1
            toks.append((text[i:j], "lit", line))
            i = j
            continue
        if c == "\"":
            j = i + 1
            while True:
                if j >= n:
                    raise ValueError("unterminated string")
                if text[j] == "\\":
                    j += 2
                    continue
                if text[j] == "\"":
                    break
                j += 1
            toks.append(("\"", "str", line))
            line += text.count("\n", i, j)
            i = j + 1
            continue
        if c == "'":
            if text.startswith("\\", i + 1):
                j = text.find("'", i + 3)
                if j < 0:
                    raise ValueError("unterminated char")
                toks.append(("'", "chr", line))
                i = j + 1
                continue
            if i + 2 < n and text[i + 2] == "'" and text[i + 1] != "\n":
                toks.append(("'", "chr", line))
                i += 3
                continue
            j = i + 1
            while j < n and (text[j] == "_" or text[j].isalnum()):
                j += 1
            toks.append((text[i:j], "life", line))
            i = j
            continue
        two = text[i:i + 2]
        if two in ("::", "->", "=>"):
            toks.append((two, "p", line))
            i += 2
            continue
        toks.append((c, "p", line))
        i += 1
    return toks


def _ex_rs_match(toks):
    """Every opening bracket's closing partner; an unbalanced file raises --
    a scanner that guessed past it would invent items."""
    pairs = {")": "(", "]": "[", "}": "{"}
    match, stack = {}, []
    for k, t in enumerate(toks):
        if t[1] != "p":
            continue
        if t[0] in ("(", "[", "{"):
            stack.append(k)
        elif t[0] in pairs:
            if not stack or toks[stack[-1]][0] != pairs[t[0]]:
                raise ValueError("unbalanced brackets at line %d" % t[2])
            match[stack.pop()] = k
    if stack:
        raise ValueError("unclosed bracket at line %d" % toks[stack[-1]][2])
    return match


def _ex_rs_is(t, word):
    return t[1] == "id" and t[0] == word


def _ex_rs_body(toks, match, k, end):
    """From `k`, the index of the item's `{` or `;` (brackets skipped), or end."""
    while k < end:
        v = toks[k][0]
        if toks[k][1] == "p" and v in ("(", "["):
            k = match[k] + 1
            continue
        if toks[k][1] == "p" and v in ("{", ";"):
            return k
        k += 1
    return end


def _ex_rs_type(ts):
    """The bare name of a type in an `impl` head: references, lifetimes,
    generics and the path cut away (`&'a mut crate::a::Foo<T>` -> `Foo`)."""
    neg = ""
    while ts and (ts[0][1] == "life" or ts[0][0] in ("&", "*", "mut", "dyn", "const", "!")):
        if ts[0][0] == "!":
            neg = "!"
        ts = ts[1:]
    depth, path = 0, []
    for t in ts:
        if t[0] == "<":
            depth += 1
        elif t[0] == ">":
            depth -= 1
        elif depth == 0:
            path.append(t)
    names = [t[0] for t in path if t[1] in ("id", "rid")]
    if path and all(t[1] in ("id", "rid") or t[0] == "::" for t in path) and names:
        return neg + names[-1]
    return neg + "".join(t[0] for t in ts)


def _ex_rs_impl(head):
    """`impl<G> [Trait for] Type [where ...]` -> (type, trait or "")."""
    if head and head[0][0] == "<":
        depth, k = 0, 0
        while k < len(head):
            if head[k][0] == "<":
                depth += 1
            elif head[k][0] == ">":
                depth -= 1
                if depth == 0:
                    break
            k += 1
        head = head[k + 1:]
    depth, cut, split = 0, len(head), -1
    for k, t in enumerate(head):
        if t[0] == "<":
            depth += 1
        elif t[0] == ">":
            depth -= 1
        elif depth == 0 and _ex_rs_is(t, "where"):
            cut = k
            break
        elif depth == 0 and _ex_rs_is(t, "for"):
            split = k
    head = head[:cut]
    if split < 0:
        return _ex_rs_type(head), ""
    return _ex_rs_type(head[split + 1:]), _ex_rs_type(head[:split])


def _ex_rs_use(ts, prefix):
    """The paths of one `use` tree: `a::{b, c}` two, `a::*` kept, `as` dropped,
    `a::{self, b}` -> `a`, `a::b`."""
    out, path, k = [], list(prefix), 0
    while k < len(ts):
        v = ts[k][0]
        if v == "::":
            if not path:
                path.append("")
            k += 1
            continue
        if v == "{":
            depth, j, part, parts = 0, k + 1, [], []
            while j < len(ts):
                w = ts[j][0]
                if w == "{":
                    depth += 1
                elif w == "}":
                    if depth == 0:
                        break
                    depth -= 1
                if w == "," and depth == 0:
                    parts.append(part)
                    part = []
                else:
                    part.append(ts[j])
                j += 1
            parts.append(part)
            for p in parts:
                if p:
                    out += _ex_rs_use(p, path)
            return out
        if _ex_rs_is(ts[k], "as"):
            break
        path.append(v)
        k += 1
    if len(path) > 1 and path[-1] == "self" and len(path) > len(prefix) and prefix:
        path = path[:-1]
    if path:
        out.append("::".join(path))
    return out


def _ex_rs_scope(ctx, i, end, parent):
    toks, match = ctx["toks"], ctx["match"]
    inherent = {}
    start = None
    while i < end:
        t = toks[i]
        v, kind = t[0], t[1]
        if kind == "p" and v == "#":
            j = i + 1
            if j < end and toks[j][0] == "!":
                j += 1
            if j < end and toks[j][0] == "[":
                i = match[j] + 1
                start = None
                continue
            i += 1
            continue
        if start is None:
            start = i
        frm = toks[start][2]
        if kind == "p":
            if v == ";":
                start = None
            elif v in ("(", "[", "{"):
                if v == "{":
                    start = None
                i = match[i] + 1
                continue
            i += 1
            continue
        nxt = toks[i + 1] if i + 1 < end else ("", "", 0)
        if kind == "id" and v == "use":
            k = i + 1
            while k < end and toks[k][0] != ";":
                k = match[k] if toks[k][0] in ("{", "(", "[") and toks[k][1] == "p" else k
                k += 1
            for target in _ex_rs_use(toks[i + 1:k], []):
                _ex_link(ctx, "import", parent, target, t[2])
            i, start = k + 1, None
            continue
        if kind == "id" and v == "macro_rules" and nxt[0] == "!" and i + 2 < end \
                and toks[i + 2][1] in ("id", "rid"):
            k = i + 3
            if k < end and toks[k][0] in ("{", "(", "["):
                close = match[k]
                if toks[k][0] != "{" and close + 1 < end and toks[close + 1][0] == ";":
                    close += 1
                _ex_node(ctx, "macro", parent, anchor_part("macro", toks[i + 2][0]),
                         frm, toks[close][2])
                i, start = close + 1, None
                continue
        if kind == "id" and v in ("fn", "struct", "enum", "trait", "mod") and nxt[1] in ("id", "rid"):
            k = _ex_rs_body(toks, match, i + 2, end)
            if v == "mod" and (k >= end or toks[k][0] != "{"):
                i, start = k + 1, None
                continue
            close = match[k] if k < end and toks[k][0] == "{" else min(k, end - 1)
            anchor = _ex_node(ctx, v, parent, anchor_part(v, nxt[0]), frm, toks[close][2])
            if v in ("trait", "mod") and k < end and toks[k][0] == "{":
                _ex_rs_scope(ctx, k + 1, close, anchor)
            i, start = close + 1, None
            continue
        if kind == "id" and v == "impl":
            k = _ex_rs_body(toks, match, i + 1, end)
            if k >= end or toks[k][0] != "{":
                i, start = k + 1, None
                continue
            close = match[k]
            ty, trait = _ex_rs_impl(toks[i + 1:k])
            name = ty + ("+" + trait if trait else "")
            if not trait and ty in inherent:
                # Methods hang on the type, not on the block: a second
                # inherent block of the same type is no item of its own.
                anchor = inherent[ty]
            else:
                anchor = _ex_node(ctx, "impl", parent, anchor_part("impl", name), frm, toks[close][2])
                if not trait:
                    inherent[ty] = anchor
            _ex_rs_scope(ctx, k + 1, close, anchor)
            i, start = close + 1, None
            continue
        i += 1


def extract_rust_scan(data, pages):
    text = _ex_text(data)
    ctx = _ex_ctx(text)
    ctx["toks"] = _ex_rs_tokens(text)
    ctx["match"] = _ex_rs_match(ctx["toks"])
    _ex_rs_scope(ctx, 0, len(ctx["toks"]), "")
    return {"nodes": ctx["nodes"], "links": ctx["links"], "parser": "scan"}


# ---- markdown: flat sections under GitHub slugs, written links

def _ex_md_links(ctx, line, sec, ln):
    # Spans already taken are blanked, never cut out: the columns stay, and
    # the links of a line come out in the order they are written.
    s = EX_MD_CODE.sub(lambda m: " " * len(m.group(0)), line)
    found = []
    ref = EX_MD_REFDEF.match(s)
    if ref:
        found.append((ref.start(1), ref.group(1)))
        s = ""
    for m in EX_MD_INLINE.finditer(s):
        found.append((m.start(1), m.group(1)))
    s = EX_MD_INLINE.sub(lambda m: " " * len(m.group(0)), s)
    for m in EX_MD_AUTO.finditer(s):
        found.append((m.start(1), m.group(1)))
    s = EX_MD_AUTO.sub(lambda m: " " * len(m.group(0)), s)
    for m in EX_MD_BARE.finditer(s):
        found.append((m.start(), m.group(0).rstrip(".,;:!?'\"")))
    found.sort(key=lambda f: f[0])
    for _, target in found:
        target = target.strip()
        if target.startswith("<") and target.endswith(">"):
            target = target[1:-1].strip()
        if not target:
            continue
        kind = "url" if EX_SCHEME.match(target) or target.startswith("//") else "link"
        _ex_link(ctx, kind, sec, target, ln)


def extract_markdown(data, pages):
    text = _ex_text(data)
    ctx = _ex_ctx(text)
    fence, sec, slugs, heads = None, "", {}, []
    for ln, raw in enumerate(ctx["lines"], 1):
        line = raw.rstrip("\r")
        f = EX_MD_FENCE.match(line)
        if fence is not None:
            if f and f.group(1)[0] == fence[0] and len(f.group(1)) >= fence[1] and not f.group(2).strip():
                fence = None
            continue
        if f and not (f.group(1)[0] == "`" and "`" in f.group(2)):
            fence = (f.group(1)[0], len(f.group(1)))
            continue
        h = EX_MD_HEAD.match(line)
        if h:
            title = re.sub(r"(^|[ \t]+)#+$", "", h.group(2) or "").strip()
            base = md_slug(title)
            slug = base
            while slug in slugs:
                slugs[base] += 1
                slug = "%s-%d" % (base, slugs[base])
            slugs[slug] = 0
            sec = _ex_node(ctx, "sec", "", anchor_part("sec", slug), ln, ln)
            heads.append((len(ctx["nodes"]) - 1, len(h.group(1))))
        _ex_md_links(ctx, line, sec, ln)
    total = len(ctx["lines"])
    if total > 1 and ctx["lines"][-1] == "":
        total -= 1
    for k, (idx, level) in enumerate(heads):
        to = total
        for idx2, level2 in heads[k + 1:]:
            if level2 <= level:
                to = ctx["nodes"][idx2]["from"] - 1
                break
        ctx["nodes"][idx]["to"] = max(ctx["nodes"][idx]["from"], to)
    return {"nodes": ctx["nodes"], "links": ctx["links"], "parser": "markdown"}


# ---- json / toml: keys as RFC 6901 pointers, arrays only as their key

def _ex_pointer(parts):
    return "".join("/" + str(p).replace("~", "~0").replace("/", "~1") for p in parts)


def _ex_json_tokens(text):
    toks, i, n, line = [], 0, len(text), 1
    while i < n:
        c = text[i]
        if c == "\n":
            line += 1
            i += 1
        elif c in " \t\r":
            i += 1
        elif c == "\"":
            j = i + 1
            while j < n and text[j] != "\"":
                j += 2 if text[j] == "\\" else 1
            toks.append(("s", json.loads(text[i:j + 1]), line))
            i = j + 1
        elif c in "{}[]:,":
            toks.append((c, None, line))
            i += 1
        else:
            j = i
            while j < n and text[j] not in " \t\r\n{}[]:,\"":
                j += 1
            toks.append(("v", text[i:j], line))
            i = j
    return toks


def _ex_json_value(ctx, toks, i, parts, parent, depth):
    """Walk one value from token `i`; returns (next index, its last line)."""
    t = toks[i]
    if t[0] == "[":
        level = 0
        while True:
            if toks[i][0] in ("[", "{"):
                level += 1
            elif toks[i][0] in ("]", "}"):
                level -= 1
                if level == 0:
                    return i + 1, toks[i][2]
            i += 1
    if t[0] != "{":
        return i + 1, t[2]
    i += 1
    if toks[i][0] == "}":
        return i + 1, toks[i][2]
    while True:
        key = toks[i]
        sub = parts + [key[1]]
        idx, anchor = None, parent
        if len(sub) <= depth:
            anchor = _ex_node(ctx, "key", parent, anchor_part("key", _ex_pointer(sub)), key[2], key[2])
            idx = len(ctx["nodes"]) - 1
        i, last = _ex_json_value(ctx, toks, i + 2, sub, anchor, depth)
        if idx is not None:
            ctx["nodes"][idx]["to"] = last
        if toks[i][0] == ",":
            i += 1
            continue
        return i + 1, toks[i][2]


def extract_json_at(data, depth):
    text = _ex_text(data)
    json.loads(text)
    ctx = _ex_ctx(text)
    _ex_json_value(ctx, _ex_json_tokens(text), 0, [], "", depth)
    return {"nodes": ctx["nodes"], "links": [], "parser": "json"}


def extract_json(data, pages):
    return extract_json_at(data, EX_KEY_DEPTH_CAP)


def _ex_toml_key(s, pos):
    parts = []
    while True:
        while pos < len(s) and s[pos] in " \t":
            pos += 1
        if pos < len(s) and s[pos] == "\"":
            j = pos + 1
            while j < len(s) and s[j] != "\"":
                j += 2 if s[j] == "\\" else 1
            parts.append(json.loads(s[pos:j + 1]))
            pos = j + 1
        elif pos < len(s) and s[pos] == "'":
            j = s.find("'", pos + 1)
            parts.append(s[pos + 1:j])
            pos = j + 1
        else:
            m = EX_TOML_BARE.match(s, pos)
            if not m:
                raise ValueError("no key")
            parts.append(m.group(0))
            pos = m.end()
        while pos < len(s) and s[pos] in " \t":
            pos += 1
        if pos < len(s) and s[pos] == ".":
            pos += 1
            continue
        return parts, pos


def _ex_toml_end(lines, i, col):
    """The last line of a value starting at (`i`, `col`): brackets and
    multi-line strings may carry it over several lines."""
    depth, quote = 0, None
    while i < len(lines):
        s, k = lines[i], col
        while k < len(s):
            if quote:
                if quote[0] == "\"" and s[k] == "\\":
                    k += 2
                    continue
                if s.startswith(quote, k):
                    k += len(quote)
                    quote = None
                    continue
                k += 1
                continue
            c = s[k]
            if c == "#":
                break
            if c in "\"'":
                quote = c * 3 if s.startswith(c * 3, k) else c
                k += len(quote)
                continue
            if c in "[{":
                depth += 1
            elif c in "]}":
                depth -= 1
            k += 1
        if quote is not None and len(quote) == 1:
            quote = None
        if depth <= 0 and quote is None:
            return i
        i, col = i + 1, 0
    return len(lines) - 1


def _ex_toml_lookup(doc, parts):
    """The value at `parts`; None past an array (its tables are no nodes)."""
    cur = doc
    for p in parts:
        cur = cur.get(p) if isinstance(cur, dict) else None
    return cur


def _ex_toml_ensure(ctx, doc, known, parts, frm, to, depth):
    """A node for every prefix of `parts` not seen yet; none inside an array."""
    parent = ""
    for k in range(1, len(parts) + 1):
        sub = tuple(parts[:k])
        if sub in known:
            parent = known[sub]
            if parent is None:
                return None
            continue
        if k > depth:
            return None
        up = _ex_toml_lookup(doc, parts[:k - 1])
        if isinstance(up, list):
            known[sub] = None
            return None
        parent = _ex_node(ctx, "key", parent, anchor_part("key", _ex_pointer(sub)), frm, to)
        known[sub] = parent
    return parent


def _ex_toml_inline(ctx, value, parts, parent, frm, to, depth):
    if not isinstance(value, dict) or len(parts) >= depth:
        return
    for key, sub in value.items():
        anchor = _ex_node(ctx, "key", parent, anchor_part("key", _ex_pointer(parts + [key])), frm, to)
        _ex_toml_inline(ctx, sub, parts + [key], anchor, frm, to, depth)


def extract_toml_at(data, depth):
    import tomllib
    text = _ex_text(data)
    doc = tomllib.loads(text)
    ctx = _ex_ctx(text)
    lines = [l.rstrip("\r") for l in ctx["lines"]]
    known, table, open_tables, last, i = {}, [], [], 0, 0
    while i < len(lines):
        s = lines[i].strip()
        if not s or s.startswith("#"):
            i += 1
            continue
        if s.startswith("["):
            for idx in open_tables:
                ctx["nodes"][idx]["to"] = max(ctx["nodes"][idx]["from"], last)
            arr = s.startswith("[[")
            table, _ = _ex_toml_key(s, 2 if arr else 1)
            before = len(ctx["nodes"])
            _ex_toml_ensure(ctx, doc, known, table, i + 1, i + 1, depth)
            open_tables = list(range(before, len(ctx["nodes"])))
            last = i + 1
            i += 1
            continue
        col = len(lines[i]) - len(lines[i].lstrip())
        parts, pos = _ex_toml_key(lines[i], col)
        end = _ex_toml_end(lines, i, pos + 1)
        full = table + parts
        parent = _ex_toml_ensure(ctx, doc, known, full, i + 1, end + 1, depth)
        if parent is not None:
            value = _ex_toml_lookup(doc, full)
            _ex_toml_inline(ctx, value, full, parent, i + 1, end + 1, depth)
        last = end + 1
        i = end + 1
    for idx in open_tables:
        ctx["nodes"][idx]["to"] = max(ctx["nodes"][idx]["from"], last)
    return {"nodes": ctx["nodes"], "links": [], "parser": "toml"}


def extract_toml(data, pages):
    return extract_toml_at(data, EX_KEY_DEPTH_CAP)


# ---- pdf: one node per page of the derived text

def extract_pdf(data, pages):
    if pages is None:
        raise ValueError("no page text")
    ctx = _ex_ctx("")
    rows = sorted(pages, key=lambda p: int(p.get("part") or 0))
    for p in rows:
        n = int(p.get("part") or 0)
        body = str(p.get("text", p.get("body")) or "")
        first = next((l for l in body.split("\n") if l.strip()), "")
        _ex_node(ctx, "page", "", anchor_part("page", n), n, n, "page", first)
    return {"nodes": ctx["nodes"], "links": [], "parser": "pdf"}


# ---- the file vector of `near`: a bitwise majority over the section bits

def file_vector(blobs):
    """The bitwise majority (a tie is 1) over the sign bits `./embed` packs
    per section, base64 like them; "" when there is none or they differ in
    length."""
    raws = []
    for b in blobs or []:
        try:
            raws.append(base64.b64decode(str(b), validate=True))
        except (ValueError, TypeError):
            return ""
    if not raws or len({len(r) for r in raws}) != 1 or not raws[0]:
        return ""
    out = bytearray(len(raws[0]))
    for i in range(len(out)):
        for bit in range(8):
            mask = 1 << (7 - bit)
            if 2 * sum(1 for r in raws if r[i] & mask) >= len(raws):
                out[i] |= mask
    return base64.b64encode(bytes(out)).decode("ascii")


def hamming_b64(a, b):
    try:
        x = base64.b64decode(str(a), validate=True)
        y = base64.b64decode(str(b), validate=True)
    except (ValueError, TypeError):
        return None
    if len(x) != len(y) or not x:
        return None
    return sum(bin(p ^ q).count("1") for p, q in zip(x, y))


EXTRACTORS = {
    "python": [extract_python_ast, extract_python_scan],
    "rust": [extract_rust_scan],
    "markdown": [extract_markdown],
    "json": [extract_json],
    "toml": [extract_toml],
    "pdf": [extract_pdf],
}


def _ex_int(limits, key):
    v = (limits or {}).get(key)
    try:
        return max(0, int(float(v)))
    except (TypeError, ValueError):
        return EX_DEFAULTS[key]


def extract(path, mime, data, pages, limits):
    """The one entry point: format, size cap, the fallback chain, the key
    depth, resolved links, the caps. Never raises; what went wrong is the
    `mark` (`no_extractor`, `too_large`, `unparsable`, `truncated`)."""
    out = {"fmt": "", "parser": "", "mark": "", "nodes": [], "links": []}
    fmt = format_of(path, mime)
    if fmt is None:
        out["mark"] = "no_extractor"
        return out
    out["fmt"] = fmt
    data = bytes(data or b"")
    if fmt == "pdf":
        size = sum(len(str(p.get("text", p.get("body")) or "").encode("utf-8")) for p in pages or [])
    else:
        size = len(data)
    if size > _ex_int(limits, "extract_max_bytes"):
        out["mark"] = "too_large"
        return out
    if fmt != "pdf" and not data:
        return out
    got = None
    for fn in EXTRACTORS.get(fmt, []):
        try:
            got = fn(data, pages)
        except Exception:
            continue
        break
    if got is None:
        out["mark"] = "unparsable"
        return out
    nodes, depth = [], {}
    keep = _ex_int(limits, "key_depth")
    for n in got["nodes"]:
        if n["kind"] == "key":
            depth[n["anchor"]] = depth.get(n["parent"], 0) + 1
            if depth[n["anchor"]] > keep:
                continue
        nodes.append(dict(n, parser=got["parser"]))
    links, once = [], set()
    for l in got["links"]:
        target = l["target_name"]
        if l["kind"] == "link":
            target = resolve_link(path, target)
            if target is None:
                continue
        # The alias is part of what an import is: `import m as a` and
        # `import m as b` bind two names, two links.
        key = (l["from_anchor"], l["kind"], target, l.get("alias", ""))
        if key in once:
            continue
        once.add(key)
        links.append(dict(l, target_name=target))
    out["parser"] = got["parser"]
    if len(nodes) > _ex_int(limits, "nodes_max") or len(links) > _ex_int(limits, "links_max"):
        out["mark"] = "truncated"
    out["nodes"] = nodes[:_ex_int(limits, "nodes_max")]
    out["links"] = links[:_ex_int(limits, "links_max")]
    return out
# ---- extractors end


# ---------------------------------------------------------------- the program

def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def emit(msgs):
    # OR-FJ.L.8: a body with none of `messages`/`system`/`attachments` is no
    # UBF body, and a debug colony dead-letters it without an answer
    # (`invalid_ubf_body`) -- measured in the gh908 colony lock on the
    # `in_check` of `write`. Every emission leaves with its slot.
    for m in msgs:
        if isinstance(m, dict) and not any(k in m for k in ("messages", "system", "attachments")):
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def say(msg):
    sys.stderr.write("file-space/derive: %s\n" % msg)


def sel(table, columns, where, order=None, limit=1):
    a = {"operation": "select", "table": table, "columns": columns, "where": where,
         "limit": limit}
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    return a


def ins(table, row):
    return {"operation": "insert", "table": table, "row": row}


def upd(table, values, where):
    return {"operation": "update", "table": table, "set": values, "where": where}


def dele(table, where):
    return {"operation": "delete", "table": table, "where": where}


def st(ops, phase, job):
    return {"header": {"route": "derive_store", "phase": phase, "reply_cell": ME, "job": job},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def mine(job):
    return {"op_id": job, "cell": ME}


def park_ops(job, state):
    return [("p-upd", upd("pending", {"body": json.dumps(state)}, mine(job))),
            ("p", sel("pending", ["body"], mine(job)))]


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": "", "op": "", "rows": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""), {"payload": None})
                leg["error_code"] = str(r.get("error_code") or "")
                leg["op"] = str(r.get("operation") or "")
                leg["rows"] = r.get("rows_affected") or 0
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
        leg["op"] = str(hop.get("operation") or "")
        leg["rows"] = hop.get("rows_affected") or 0
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def first(lg, cid):
    r = rows(lg, cid)
    return r[0] if r else None


def affected(lg, cid):
    """Rows the leg `cid` wrote; 0 for a refused or a missing leg."""
    try:
        return int((lg.get(cid) or {}).get("rows") or 0)
    except (TypeError, ValueError):
        return 0


def taken(lg, cid):
    """The insert `cid` met a row with its unique key (GH #947): somebody
    else was first, which is an answer, not a store error."""
    return str((lg.get(cid) or {}).get("error_code") or "") == "unique_violation"


def errors(lg):
    # A claim or a directory row inserted by the sync job (GH #947) may meet
    # its unique key: that is how the job learns it lost, never a failure.
    return ["%s: %s" % (k, v["error_code"]) for k, v in lg.items() if v.get("error_code")
            and not (v["error_code"] == "unique_violation" and k.startswith(("s-claim", "di-")))]


def parked(lg):
    r = first(lg, "p")
    try:
        return json.loads(str((r or {}).get("body") or ""))
    except Exception:
        return None


def answer_msg(req, fields=None, code=None, message="", extra=None):
    body = {"ok": code is None, "op": req.get("op", ""), "op_id": req.get("op_id", "")}
    if code is None:
        body.update(fields or {})
    else:
        # A refusal carries its extras inside `error` and no top-level
        # `version` (OR-FH-83, README 2.2 `error: {code, message, current?}`).
        body["error"] = {"code": code, "message": message}
        body["error"].update(extra or {})
    return {"header": {"route": "answer", "op": body["op"], "op_id": body["op_id"],
                       "caller": req.get("caller", "")}, **body}


def answer(req, fields=None, code=None, message="", job=None, extra=None):
    out = [answer_msg(req, fields, code, message, extra)]
    if job:
        out.append(st([("p-del", dele("pending", mine(job)))], "noop", job))
    emit(out)


def notify(req, ok, oneline):
    if str(req.get("notify") or "") != "1":
        return []
    v = str(req.get("version") or "")
    return [{"header": {"route": "derived", "caller": req.get("caller", "")},
             "file": req.get("file", ""), "version": v[:12], "ok": bool(ok),
             "oneline": oneline or ""}]


def fail_job(job, req, why):
    """A job that stops: nothing half is written, the rows already there stay,
    and whoever asked with `notify` hears it. A derive job that stops after
    its node rows (a failed embedding or summary) still syncs the file into
    its directories (GH #947): the contribution counts, without the tags or
    the vector that were not made."""
    say(why)
    emit(notify(req, False, req.get("oneline_was", ""))
         + [st([("p-del", dele("pending", mine(job)))], "noop", job)]
         + ([dirs_door(req["file"], req["version"])] if req.get("sync") else []))


def to_embed(job, texts):
    return {"header": {"route": "embed", "job": job},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": "e-" + job,
                          "text": json.dumps({"texts": texts})}]}


def to_summarizer(job, prompt, text):
    return {"header": {"route": "summarize", "job": job},
            "system": {"instructions": {"text": prompt}},
            "messages": [{"origin": "user", "type": "text", "text": text}]}


def request_of(body):
    """A request body is the JSON object itself; a `messages[]` form with the
    object as its first text is taken too."""
    if isinstance(body.get("op"), str) or isinstance(body.get("file"), str):
        return body
    for m in body.get("messages") or []:
        try:
            v = json.loads(m.get("text") or "")
        except Exception:
            continue
        if isinstance(v, dict):
            return v
    return {}


def knob_str(key, default):
    v = knobs.get(key, default)
    return default if v is None else str(v)


def knob_int(key, default):
    try:
        return int(knobs.get(key, default))
    except (TypeError, ValueError):
        return default


# ------------------------------------------------------------- sync job (GH #947)
# A `s-` job moves ONE file's contribution into the `dirs` rows of its
# ancestors. It reads the truth of the file NOW (`files`, the head's node run
# and tags) beside the contribution `contrib` last counted in -- never the
# job that started it, so a derive of a version that is no head any more
# counts nothing of its own -- and moves the difference (`agg_delta`):
#
#   s-read   the truth and `contrib`, all by file (a head other than the one
#            read for is read again, at most SYNC_READS times);
#   s-claim  the difference is claimed by a compare-and-swap on
#            `contrib.seq` (insert under its unique key, update or delete
#            where the seq read), the ancestors' rows read behind it; a lost
#            claim reads again (at most SYNC_TRIES times);
#   s-apply  ONE bundle with exactly one `update dirs` per ancestor, each a
#            compare-and-swap on its `changed_seq` (a missing row is inserted
#            first, its unique key may say somebody was faster), the rows read
#            behind them; the ancestors that lost go again with the row read
#            there (at most `agg_retries` rounds). A sibling is never read.
#
# Every bundle carries the job's state in and out (`sync_bundle`), so the job
# ends without a store round of its own and never leaves a `pending` row. It
# answers nobody and sends no event.

def sync_reads(f, hint):
    """The truth of a file's contribution -- its row, the node run and the
    tags of `hint` (the version believed to be the head) -- and the
    contribution counted in, all by file."""
    return [("s-f", sel("files", ["path", "head", "tomb", "bytes"], {"file": f})),
            ("s-c", sel("contrib", CONTRIB_COLS, {"file": f})),
            ("s-r", sel("node_runs", ["nodes", "fvec"], {"file": f, "version": hint})),
            ("s-t", sel("summaries", ["text"], {"file": f, "version": hint, "level": "tags"},
                        [("at", "desc")], 1))]


def dirs_door(f, v):
    """The sync of file `f` from version `v` on, as `in_dirs` to this cell
    again (review I-1 of GH #947): the edge restores the routing budget, a
    door, because the derive road before it (a workspace commit with its
    embedding and summary) leaves the sync almost nothing -- 47 of 48 in the
    strand's model, and every lost compare-and-swap on `/` costs two more.
    One door per derive job; the sync's own rounds are bounded below."""
    return {"header": {"route": "in_dirs"}, "file": f, "version": v, "messages": []}


def sync_bundle(sjob, sj, ops):
    return ([("p-put", ins("pending", {"op_id": sjob, "cell": ME, "phase": "sync",
                                       "body": json.dumps(sj), "at": now()}))]
            + ops + [("p", sel("pending", ["body"], mine(sjob))),
                     ("p-del", dele("pending", mine(sjob)))])


def sync_spawn(f, hint):
    """A new sync job of file `f`: one store message under its own job id
    and its own `pending` row."""
    sjob = "s-" + secrets.token_hex(8)
    sj = {"job": "sync", "file": f, "hint": hint, "reads": 1, "tries": 0, "rounds": 0}
    return [st(sync_bundle(sjob, sj, sync_reads(f, hint)), "s-read", sjob)]


def dirs_read(paths):
    return ("s-d", sel("dirs", DIR_COLS, {"path": {"in": list(paths)}}, [("path", "asc")],
                       max(1, len(paths))))


def sync_step(lg, sjob, sj):
    """The next emission of a sync job out of the reads of `sync_reads`: []
    when what `contrib` counted in is the truth (or the job gives up), else
    the claim of the difference."""
    f = sj["file"]
    fr = first(lg, "s-f") or {}
    head = str(fr.get("head") or "")
    live = bool(fr) and head != "" and str(fr.get("tomb") or "") == ""
    if live and head != sj["hint"]:
        if sj["reads"] >= SYNC_READS:
            say("sync of %s: the head kept moving -- given up, the next sync counts it" % f)
            return []
        sj.update(hint=head, reads=sj["reads"] + 1)
        return [st(sync_bundle(sjob, sj, sync_reads(f, head)), "s-read", sjob)]
    new = None
    if live:
        run = first(lg, "s-r") or {}
        new = contrib_of(f, fr.get("path"), head, fr.get("bytes"), run.get("nodes"),
                         run.get("fvec"), (first(lg, "s-t") or {}).get("text"))
    row = first(lg, "s-c")
    old = contrib_row(row)
    delta = agg_delta(old, new)
    if not delta:
        return []
    seq = int((row or {}).get("seq") or 0)
    if old is None:
        claim = ins("contrib", dict(new, tags=json.dumps(new["tags"]), seq=1))
    elif new is None:
        claim = dele("contrib", {"file": f, "seq": seq})
    else:
        vals = {k: v for k, v in new.items() if k != "file"}
        claim = upd("contrib", dict(vals, tags=json.dumps(new["tags"]), seq=seq + 1),
                    {"file": f, "seq": seq})
    sj.update(old=old, new=new, todo=sorted(delta))
    sj["left"] = sj["todo"]
    return [st(sync_bundle(sjob, sj, [("s-claim", claim), dirs_read(sj["todo"])]), "s-claim", sjob)]


def apply_ops(sj, have):
    """One `update dirs` per ancestor still to move (`sj.left`), on the row
    read last (`have`); a missing row is inserted first, empty, and updated
    from `changed_seq` 0. The ancestors of the new path live again."""
    delta = agg_delta(sj["old"], sj["new"])
    alive = set(ancestors(dir_of(sj["new"]["path"]))) if sj.get("new") else set()
    ops = []
    for p in sj["left"]:
        i = sj["todo"].index(p)
        row = have.get(p)
        if row is None:
            ops.append(("di-%d" % i, ins("dirs", {
                "path": p, "parent": dir_parent(p), "depth": dir_depth(p), "files": 0, "bytes": 0,
                "nodes": 0, "vec_counts": "[]", "vec_n": 0, "tags": "{}", "dirty": 1, "summary": "",
                "summary_seq": 0, "changed_seq": 0, "born": now(), "tomb": ""})))
        cs = int((row or {}).get("changed_seq") or 0)
        vals = dict(agg_apply(row, delta[p]), dirty=1, changed_seq=cs + 1)
        if p in alive:
            vals["tomb"] = ""
        ops.append(("du-%d" % i, upd("dirs", vals, {"path": p, "changed_seq": cs})))
    return ops + [dirs_read(sj["left"])]


# ------------------------------------------------------------- dir_summary (GH #947)

def dir_children(subs, files, cap):
    """The lines the summarizer reads of a directory: its living
    sub-directories (`<name>/: <summary or "N files">`) and files
    (`<name>: <one line>`), by path, at most `cap`."""
    out = []
    for r in subs:
        p = str(r.get("path") or "")
        s = str(r.get("summary") or "") or "%d files" % int(r.get("files") or 0)
        out.append((p, "%s/: %s" % (basename(p), s)))
    for r in files:
        p = str(r.get("path") or "")
        one = str(r.get("oneline") or "")
        out.append((p, basename(p) + (": " + one if one else "")))
    out.sort()
    lines = [l for _, l in out[:cap]]
    if len(out) > cap:
        lines.append("[... more entries not shown]")
    return lines


doc = json.load(sys.stdin)
