            answer(r, code="bad_request", message="path is required: an absolute directory path")
        r["path"] = dir_norm(raw)
        n = max(1, knob_int("dir_summary_children", DIR_SUMMARY_CHILDREN))
        job = "y-" + secrets.token_hex(8)
        # The state rides in and out of the one bundle: an answer straight
