# ------------------------------------------------------------- derive job

def done_seq(mark):
    """The main-line `seq` of the newest version derived for the file, from
    this cell's marker row (`pending` `done:<file>`): the version comparison
    runs over `line`, never over arrival order."""
    try:
        return int(json.loads(str((mark or {}).get("body") or "{}")).get("seq") or 0)
    except Exception:
        return 0


def superseded(state):
    say("%s@%s arrived after a newer version was derived -- it writes nothing"
        % (state["file"], state["version"][:12]))
    emit(notify(state, False, state.get("oneline_was", ""))
         + [st([("p-del", dele("pending", mine(job)))], "noop", job)])


def view_ops(js):
    """The reads a text view is built from: the version's blocks and its
    `derived` pages (the bundle `d-text` gets, and each model step again)."""
    uniq = sorted(set(js["hashes"]))
    # An empty file has no block (GH #900), and the store refuses an empty
    # `in`: without this leg an empty file failed `d-text` and never got its
    # one line, its node run or its `source_changed` (GH #944).
    ops = [("b", sel("blocks", ["hash", "enc", "body"], {"file": js["file"], "hash": {"in": uniq}},
                     None, len(uniq)))] if uniq else []
    return ops + [("g", sel("derived", ["part", "body"],
                            {"file": js["file"], "version": js["version"], "kind": "text"},
                            [("part", "asc")], PAGE_FETCH))]


def job_view(js):
    """(text, sections) of the job's version out of the `view_ops` answer --
    the same pure steps every time, so the sections a model step rebuilds are
    the ones `d-text` counted; (None, None) when a block went missing."""
    content = assemble_blocks(js["hashes"], rows(lg, "b"))
    text, paged = view_text(content, rows(lg, "g"))
    if text is None:
        return None, None
    kind = "pages" if paged else kind_of(js["path"], js["mime"])
    return text, sections(text, kind, knob_int("section_lines", SECTION_LINES))


def sec_marks(secs):
    return [{"section": s["section"], "from_line": s["from_line"], "to_line": s["to_line"]}
            for s in secs]


def go(state, extra=None):
    """Next step of a derive job, in the order of the plan: embeddings, then
    the summary, then the rows. `extra` leaves in the same emission (the
    `source_changed` of `d-nodes`).

    The text view never sits in `pending` (GH #907, owner ruling R-FJ-1: a
    20 MiB PDF's pages run past 1 MiB): the parked job keeps the section
    borders only, and a step that hands text to a model reads the blocks and
    pages once more (`d-embed`, `d-sum`) and rebuilds it. One store round per
    model step, the price of that ruling."""
    extra = list(extra or [])
    if state.get("want_embed") and state.get("secs") and state.get("vectors") is None:
        emit(extra + [st(view_ops(state) + [("p", sel("pending", ["body"], mine(job)))],
                         "d-embed", job)])
    if state.get("want_summary") and state.get("summary") is None:
        emit(extra + [st(view_ops(state) + [("p", sel("pending", ["body"], mine(job)))],
                         "d-sum", job)])
    f = state["file"]
    emit(extra + [st([("mark", sel("pending", ["body"], {"op_id": "done:" + f, "cell": ME})),
                      ("p", sel("pending", ["body"], mine(job)))], "d-write", job)])


# ------------------------------------------------------------- nodes (GH #944)
# The head's nodes and links are written in `d-text`, right after the text
# view and BEFORE any model step, so a summary or an embedding that fails
# later (`fail_job`) never takes them along: nodes never hang on a model.
# Price: no store round more -- the node bundle takes the place of the
# parking round `d-text` -> store -> `d-go` (`d-nodes` goes on where `d-go`
# did), so a job of the head costs the same hops as before plus the event's
# one hop out (against the ~42 hops of a write -> derive run); the event
# leaves the hive with no way back and takes nothing from the job's TTL. A
# version that is no longer head keeps the old `d-go` round. The bundle grows
# by one leg per node and link. The extraction runs inside the cell's
# timeout: `extract_max_bytes` caps what is parsed, every extractor loop is
# bounded, and the rows go in ONE bundle (the store has no many-row insert
# and no cap on the legs of a bundle; at most nodes_max + links_max + a few
# legs, like the up to 400 embedding legs of `d-write`).

def ex_limits():
    return {"nodes_max": knob_int("nodes_max", EX_DEFAULTS["nodes_max"]),
            "links_max": knob_int("links_max", EX_DEFAULTS["links_max"]),
            "extract_max_bytes": knob_int("extract_max_bytes", EX_DEFAULTS["extract_max_bytes"]),
            "key_depth": knob_int("key_depth", EX_DEFAULTS["key_depth"])}


def node_ops(f, v, seq, ex):
    """The bundle that makes the head's rows the file's only rows: first the
    rows of `v` itself go and every row of an OLDER main-line position (`seq`
    below the version's `line.seq`, or none at all -- a row from before the
    column), then the head's go in, each carrying `seq`, then `files` is read
    once more -- the bundle is no transaction, and the event waits for that
    last read to say `v` is still the living head. Never by file alone
    (GH #947, ledger 12): a bundle that arrives after a newer head's bundle
    would take the newer head's rows with it."""
    ops = []
    for t in ("nodes", "links", "node_runs"):
        ops.append(("nx-" + t, dele(t, {"file": f, "version": v})))
        ops.append(("ns-" + t, dele(t, {"file": f, "seq": {"or_null": {"lt": seq}}})))
    for i, n in enumerate(ex["nodes"]):
        ops.append(("n-%d" % i, ins("nodes", {
            "file": f, "version": v, "anchor": n["anchor"], "kind": n["kind"],
            "parent": n["parent"], "unit": n["unit"], "from_pos": n["from"], "to_pos": n["to"],
            "oneline": n["oneline"], "parser": n["parser"], "seq": seq})))
    for i, l in enumerate(ex["links"]):
        ops.append(("l-%d" % i, ins("links", {
            "file": f, "version": v, "from_anchor": l["from_anchor"], "kind": l["kind"],
            "target_name": l["target_name"], "pos": l["pos"], "alias": l.get("alias", ""),
            "seq": seq})))
    ops.append(("nr", ins("node_runs", {
        "file": f, "version": v, "fmt": ex["fmt"], "parser": ex["parser"], "mark": ex["mark"],
        "nodes": len(ex["nodes"]), "links": len(ex["links"]), "fvec": "", "seq": seq})))
    ops.append(("h2", sel("files", ["head", "tomb"], {"file": f})))
    return ops


def living_head(row, v):
    return bool(row) and str(row.get("head") or "") == v and str(row.get("tomb") or "") == ""


def source_changed(js):
    """The node source contract (README "Nodes and links"): one per head
    move, no `caller` in the head -- it leaves the hive whoever wrote."""
    run = js["run"]
    return {"header": {"route": "source_changed"}, "source": js["file"],
            "version": js["version"][:12], "path": js.get("path") or "",
            "fmt": run["fmt"], "parser": run["parser"], "mark": run["mark"],
            "nodes": run["nodes"], "links": run["links"], "tomb": False}


def source_described(js, lg):
    """What a file is about, for whoever keeps a catalog of the space
    (GH #947): one `{source, version (12 hex), path, oneline, tags}` per
    summary stored for a living head, no `caller` in the head -- it leaves
    the hive whoever wrote, like `source_changed`, which stays the one event
    of the head move itself. Read off the `d-write` answer: `f-one` laid the
    one line on the head (one row: `v` was still the head), and the file's
    row read behind it (`s-f`) says the head is living -- a removal keeps the
    head and sets `tomb` -- and where the file lives now (a move keeps the
    head and changes the path). No summary stored (none wanted, or a failed
    one, which never gets here) or a head that moved on: nothing -- the job
    of the newer head describes it."""
    sm = js.get("summary")
    row = first(lg, "s-f")
    if not sm or affected(lg, "f-one") != 1 or not living_head(row, js["version"]):
        return []
    return [{"header": {"route": "source_described"}, "source": js["file"],
             "version": js["version"][:12], "path": str(row.get("path") or js.get("path") or ""),
             "oneline": sm["oneline"], "tags": tags_norm(sm.get("tags") or [])}]


if phase == "d-load":
    f = first(lg, "f")
    if not f:
        fail_job(job, js, "in_derive for unknown file %s" % js["file"])
    vs = [r for r in rows(lg, "v") if str(r.get("version") or "").startswith(js["version"])]
    if len(vs) != 1:
        fail_job(job, js, "in_derive: %d versions of %s match %s" % (len(vs), js["file"], js["version"]))
    hashes = block_hashes(vs[0].get("blocks"))
    if hashes is None:
        fail_job(job, js, "version %s of %s has no readable block list" % (js["version"], js["file"]))
    js.update({"version": str(vs[0]["version"]), "path": str(f.get("path") or ""),
              "mime": str(f.get("mime") or ""), "fkind": str(f.get("kind") or ""),
              "bytes": vs[0].get("bytes") or f.get("bytes") or 0,
              "oneline_was": str(f.get("oneline") or ""),
              "born": not rows(lg, "born")})
    fw = {"file": js["file"], "version": js["version"]}
    js["hashes"] = hashes
    # `h`: is the version still the living head when `d-text` runs? Only then
    # are its nodes written (GH #944).
    emit([st([("l", sel("line", ["seq"], fw, [("seq", "desc")], 1))] + view_ops(js)
             + [("mark", sel("pending", ["body"], {"op_id": "done:" + js["file"], "cell": ME})),
                ("h", sel("files", ["head", "tomb"], {"file": js["file"]}))]
             + park_ops(job, js), "d-text", job)])

if phase == "d-text":
    line = first(lg, "l")
    if not line:
        fail_job(job, js, "version %s of %s is not on the main line -- nothing derived"
                 % (js["version"][:12], js["file"]))
    js["seq"] = int(line.get("seq") or 0)
    if done_seq(first(lg, "mark")) > js["seq"]:
        # Checked here, before a model or the endpoint is paid, and once more
        # right before the rows are written (`d-write`).
        superseded(js)
    content = assemble_blocks(js["hashes"], rows(lg, "b"))
    if content is None:
        fail_job(job, js, "version %s of %s misses a block -- nothing derived"
                 % (js["version"][:12], js["file"]))
    text, paged = view_text(content, rows(lg, "g"))
    js["want_summary"] = bool(js["born"]) or knob_str("summary_on_commit", "1") == "1"
    js["want_embed"] = knob_str("embed", "1") == "1"
    if text is None or not text.strip():
        # No text view (or an empty file): the one line comes from name and
        # type, without a model, and nothing is embedded.
        js["want_embed"] = False
        js["secs"] = []
        if js["want_summary"]:
            js["summary"] = {"oneline": name_oneline(js["path"], js["mime"], js["fkind"], js["bytes"]),
                            "short": "", "model": ""}
    else:
        kind = "pages" if paged else kind_of(js["path"], js["mime"])
        secs = sections(text, kind, knob_int("section_lines", SECTION_LINES))
        # borders only: the text is rebuilt by the step that needs it (`go`)
        js["secs"] = sec_marks(secs) if js["want_embed"] else []
    js.setdefault("summary", None)
    js["vectors"] = None
    # From here on every end of the job syncs the file into its directories
    # (GH #947), a failed model step included.
    js["sync"] = True
    if living_head(first(lg, "h"), js["version"]):
        # The raw bytes, not the text view: an extractor parses the file as
        # written; a PDF's pages are its `derived` rows ({part, body}). A file
        # without a text view still gets its run (`no_extractor`, or a
        # format's mark) and its event.
        ex = extract(js["path"], js["mime"], content, rows(lg, "g") or None, ex_limits())
        js["run"] = {"fmt": ex["fmt"], "parser": ex["parser"], "mark": ex["mark"],
                     "nodes": len(ex["nodes"]), "links": len(ex["links"])}
        # `seq` (the version's `line.seq`, read above) is set before the rows
        # that carry it are made.
        emit([st(node_ops(js["file"], js["version"], js["seq"], ex) + park_ops(job, js),
                 "d-nodes", job)])
    # Not the head any more (or removed): no rows, no event -- the head's
    # own job writes them; the summary and the embedding go on as before.
    emit([st(park_ops(job, js), "d-go", job)])

if phase == "d-nodes":
    if bad:
        # A refused leg leaves no half run behind (GH #947, ledger 13): the
        # run row of the version goes FIRST -- a reader that finds no run
        # computes the nodes itself, one that finds a run trusts the rows --
        # then the version's nodes and links that did go in.
        say("nodes of %s@%s not written, no source_changed: %s"
            % (js["file"], js["version"][:12], "; ".join(bad)))
        go(js, [st([("nz-" + t, dele(t, {"file": js["file"], "version": js["version"]}))
                    for t in ("node_runs", "nodes", "links")], "noop", job)])
    if living_head(first(lg, "h2"), js["version"]):
        go(js, [source_changed(js)])
    # The head moved (or the file was removed) while the rows went in: they
    # are taken back by version, which can never hit the newer head's rows,
    # and the newer head's job sends the one event. The run row first, as on
    # a refusal (GH #947, ledger 13).
    go(js, [st([("nz-" + t, dele(t, {"file": js["file"], "version": js["version"]}))
                for t in ("node_runs", "nodes", "links")], "noop", job)])

if phase == "d-go":
    go(js)

if phase in ("d-embed", "d-sum"):
    text, secs = job_view(js)
    if text is None or (phase == "d-embed" and sec_marks(secs) != js["secs"]):
        fail_job(job, js, "the text view of %s@%s changed under the job -- nothing derived"
                 % (js["file"], js["version"][:12]))
    if phase == "d-embed":
        emit([to_embed(job, [s["text"][:EMBED_MAX_CHARS] or s["section"] for s in secs])])
    emit([to_summarizer(job, SUMMARY_PROMPT, summary_input(js["path"], text, secs))])

if phase == "embedded" and job.startswith("d-"):
    got = incoming()
    vec = got.get("vectors")
    if not isinstance(vec, list) or len(vec) != len(js.get("secs") or []) or \
            not all(isinstance(x, str) and x for x in vec):
        fail_job(job, js, "embedding %s@%s failed: %s" % (js["file"], js["version"][:12],
                                                          got.get("error") or "no vectors"))
    js["vectors"] = vec
    js["emodel"] = str(got.get("model") or "")
    js["edim"] = got.get("dim")
    emit([st(park_ops(job, js), "d-go", job)])

if phase == "summary" and job.startswith("d-"):
    got = incoming()
    parsed = parse_summary(got.get("text")) if got.get("finish") == "stop" else None
    if not parsed:
        fail_job(job, js, "summary of %s@%s failed (finish %r, error %r) -- the older summary stays"
                 % (js["file"], js["version"][:12], got.get("finish"), got.get("error_code")))
    js["summary"] = {"oneline": parsed[0], "short": parsed[1], "tags": parsed[2],
                     "model": got.get("model", "")}
    emit([st(park_ops(job, js), "d-go", job)])

if phase == "d-write":
    f, v = js["file"], js["version"]
    if done_seq(first(lg, "mark")) > js["seq"]:
        superseded(js)
    at = now()
    ops = []
    if js.get("vectors") is not None:
        ops.append(("e-del", dele("embeddings", {"file": f, "version": v})))
        for i, (s, vec) in enumerate(zip(js["secs"], js["vectors"])):
            ops.append(("e-%d" % i, ins("embeddings", {
                "file": f, "version": v, "section": s["section"], "from_line": s["from_line"],
                "to_line": s["to_line"], "blob": vec, "dim": js.get("edim") or 0,
                "model": js.get("emodel") or ""})))
        # The file vector `near` compares (GH #944): only for (file, v), so a
        # version that is no longer head sets nothing (zero rows is ok).
        fv = file_vector(js["vectors"])
        if fv:
            ops.append(("r-fvec", upd("node_runs", {"fvec": fv}, {"file": f, "version": v})))
    one = js.get("oneline_was", "")
    if js.get("summary"):
        sm = js["summary"]
        one = sm["oneline"]
        ops.append(("s-one", ins("summaries", {"file": f, "version": v, "level": "oneline",
                                               "text": sm["oneline"], "model": sm["model"], "at": at})))
        if sm["short"]:
            ops.append(("s-short", ins("summaries", {"file": f, "version": v, "level": "short",
                                                     "text": sm["short"], "model": sm["model"],
                                                     "at": at})))
        # The topics of the version (GH #947), an empty list too: the sync
        # counts them into every directory above the file.
        ops.append(("s-tags", ins("summaries", {"file": f, "version": v, "level": "tags",
                                                "text": json.dumps(tags_norm(sm.get("tags") or [])),
                                                "model": sm["model"], "at": at})))
        # Only while `v` is still the head (OR-FH-72): a slow job of an older
        # version never lays its one line over a newer head; zero rows is ok
        # (and no `source_described`, GH #947: its rows_affected is the gate).
        ops.append(("f-one", upd("files", {"oneline": one}, {"file": f, "head": v})))
    js["oneline_now"] = one
    ops += [("m-del", dele("pending", {"op_id": "done:" + f, "cell": ME})),
            ("m-put", ins("pending", {"op_id": "done:" + f, "cell": ME, "phase": v,
                                      "body": json.dumps({"seq": js["seq"]}), "at": at})),
            ("p-upd", upd("pending", {"body": json.dumps(js)}, mine(job))),
            ("p", sel("pending", ["body"], mine(job))),
            ("p-del", dele("pending", mine(job)))]
    # The file's row read behind the rows just written (the bundle runs its
    # legs in order): `source_described` reads the living head and the path
    # there. The sync itself starts behind its door (`dirs_door`).
    emit([st(ops + sync_reads(f, v)[:1], "d-done", job)])

if phase == "d-done":
    # The derive job ends here; its sync goes on under a job of its own,
    # behind its door. The description of a living head leaves beside it, at
    # most one (GH #947).
    emit(notify(js, True, js.get("oneline_now", ""))
         + source_described(js, lg)
         + [dirs_door(js["file"], js["version"])])

# ------------------------------------------------------------- sync job

if phase == "s-read":
    emit(sync_step(lg, job, js))

if phase == "s-claim":
    if affected(lg, "s-claim") < 1 or taken(lg, "s-claim"):
        # Another sync moved `contrib` since this one read it: read again.
        js["tries"] += 1
        if js["tries"] > SYNC_TRIES:
            say("sync of %s lost its claim %d times -- given up" % (js["file"], js["tries"]))
            emit([])
        hint = js["new"]["version"] if js.get("new") else js["hint"]
        js.update(hint=hint, reads=1)
        emit([st(sync_bundle(job, js, sync_reads(js["file"], hint)), "s-read", job)])
    emit([st(sync_bundle(job, js, apply_ops(js, {str(r.get("path")): r for r in rows(lg, "s-d")})),
             "s-apply", job)])

if phase == "s-apply":
    lost = [p for p in js["left"] if affected(lg, "du-%d" % js["todo"].index(p)) < 1]
    if not lost:
        emit([])
    js["rounds"] += 1
    if js["rounds"] > max(0, knob_int("agg_retries", AGG_RETRIES)):
        say("sync of %s: %s still lost after %d rounds -- the directories drift"
            % (js["file"], ", ".join(lost), js["rounds"] - 1))
        emit([])
    js["left"] = lost
    emit([st(sync_bundle(job, js, apply_ops(js, {str(r.get("path")): r for r in rows(lg, "s-d")})),
             "s-apply", job)])

# ------------------------------------------------------------- dir_summary job

if phase == "y-load":
    row = first(lg, "y-d")
    path = js["path"]
    # The root always is, with or without its row (a missing one reads as
    # the empty row); any other path needs a living row.
    if path != "/" and (not row or str(row.get("tomb") or "")):
        answer(js, code="not_found", message="no directory %r" % path)
    row = row or {}
    cs = int(row.get("changed_seq") or 0)
    if not int(row.get("dirty") or 0) and int(row.get("summary_seq") or 0) == cs:
        answer(js, {"path": path, "summary": str(row.get("summary") or ""), "fresh": False})
    n = max(1, knob_int("dir_summary_children", DIR_SUMMARY_CHILDREN))
    lines = dir_children(rows(lg, "y-s"), rows(lg, "y-f"), n)
    clean = upd("dirs", {"summary": "", "dirty": 0, "summary_seq": cs},
                {"path": path, "changed_seq": cs})
    if not lines:
        # Nothing under it: the empty summary, no model, the row clean.
        emit([answer_msg(js, {"path": path, "summary": "", "fresh": True}),
              st([("y-upd", clean)], "noop", job)])
    js["cs"] = cs
    # The park goes out FIRST, as for `ask`: the store takes it long before
    # the summarizer's answer asks for it.
    emit([st([("p-put", ins("pending", {"op_id": job, "cell": ME, "phase": "dir_summary",
                                        "body": json.dumps(js), "at": now()}))], "noop", job),
          to_summarizer(job, DIR_SUMMARY_PROMPT, "Directory: %s\n\n%s" % (path, "\n".join(lines)))])

if phase == "summary" and job.startswith("y-"):
    got = incoming()
    parsed = parse_summary(got.get("text")) if got.get("finish") == "stop" else None
    if not parsed:
        answer(js, code="summary_failed", job=job,
               message="the summarizer gave no summary of %s (finish %r, error %r)"
               % (js["path"], got.get("finish"), got.get("error_code")))
    # Stored only while nothing changed since the read (`changed_seq`): a
    # change in between keeps the directory dirty, the answer goes out anyway.
    emit([answer_msg(js, {"path": js["path"], "summary": parsed[0], "fresh": True}),
          st([("y-upd", upd("dirs", {"summary": parsed[0], "dirty": 0, "summary_seq": js["cs"]},
                            {"path": js["path"], "changed_seq": js["cs"]})),
              ("p-del", dele("pending", mine(job)))], "noop", job)])

# --------------------------------------------------------------- read job

def v12(v):
    return str(v or "")[:12]


def check_version(js, v):
    """The version is known: look for its embeddings (of the one file), its
    block list and, for `ask`, a summary."""
    js["v"] = v
    fw = {"file": js["f"], "version": v}
    ops = [("e", sel("embeddings", ["model"], fw)),
           ("v", sel("versions", ["blocks"], fw))]
    if js["op"] == "ask":
        ops.append(("s", sel("summaries", ["text", "version"], {"file": js["f"], "level": "short"},
                             [("at", "desc")], 1)))
    emit([st(ops + park_ops(job, js), "r-check", job)])


if phase == "r-file":
    f = first(lg, "f")
    if not f:
        answer(js, code="not_found", message="no file at %r" % js["addr"], job=job)
    js["f"], js["path"] = str(f.get("file") or ""), str(f.get("path") or "")
    a = js["a"]
    # As `read`: a removed file is tombstoned at its head; its versions and
    # snapshots stay addressable.
    if a["at"] == "head" and not js["ws"] and str(f.get("tomb") or ""):
        answer(js, code="tombstoned", message="%s was removed" % js["f"], job=job)
    ws = first(lg, "w-name")
    if js["ws"]:
        if not ws or str(ws.get("state") or "") != "open":
            answer(js, code="ws_unknown", message="no open workspace %r" % (a["ref"] or js["ws"]),
                   job=job)
        js["wsid"] = str(ws.get("ws") or "")
        emit([st([("wf", sel("ws_files", ["working", "state"], {"ws": js["wsid"], "file": js["f"]})),
                  ("wl", sel("line", ["version"], {"file": js["f"], "seq": {"lte": ws.get("base_seq") or 0}},
                             [("seq", "desc")], 1))] + park_ops(job, js), "r-ver", job)])
    if a["at"] == "v":
        emit([st([("vv", sel("versions", ["version"], {"file": js["f"], "version": {"gte": a["ref"]}},
                             [("version", "asc")], 2))] + park_ops(job, js), "r-ver", job)])
    if a["at"] == "snap":
        emit([st([("sn", sel("snaps", ["version"], {"file": js["f"], "name": a["ref"]},
                             [("at", "desc")], 1))] + park_ops(job, js), "r-ver", job)])
    if not str(f.get("head") or ""):
        answer(js, code="not_found", message="%s has no main line yet" % js["f"], job=job)
    check_version(js, str(f["head"]))

if phase == "r-ver":
    a = js["a"]
    if "wsid" in js:
        wf = first(lg, "wf")
        if wf and str(wf.get("state") or "") != "removed":
            # A touched file reads its working version, and working versions
            # are never derived: nothing to rank.
            answer(js, fields=None, code="not_indexed", job=job,
                   message="working versions are not indexed",
                   extra={"current": v12(wf.get("working"))})
        wl = first(lg, "wl")
        if not wl:
            answer(js, code="not_found", message="%s is not in the workspace" % js["f"], job=job)
        check_version(js, str(wl.get("version") or ""))
    if a["at"] == "v":
        vs = [str(r.get("version") or "") for r in rows(lg, "vv")
              if str(r.get("version") or "").startswith(a["ref"])]
        if not vs:
            answer(js, code="version_unknown", message="%s has no version %s" % (js["f"], a["ref"]),
                   job=job)
        if len(vs) > 1:
            answer(js, code="version_ambiguous", message="%s names more than one version" % a["ref"],
                   job=job, extra={"candidates": [v12(x) for x in vs]})
        check_version(js, vs[0])
    sn = first(lg, "sn")
    if not sn:
        answer(js, code="snap_unknown", message="%s has no snapshot %r" % (js["f"], a["ref"]),
               job=job)
    check_version(js, str(sn.get("version") or ""))

if phase == "r-check":
    hashes = block_hashes((first(lg, "v") or {}).get("blocks"))
    if hashes is None:
        answer(js, code="version_unknown", message="%s has no version %s" % (js["f"], v12(js["v"])),
               job=job)
    js["indexed"] = bool(rows(lg, "e"))
    s = first(lg, "s")
    js["summary"] = str((s or {}).get("text") or "")
    js["hashes"] = hashes
    uniq = sorted(set(hashes))
    emit([st([("b", sel("blocks", ["hash", "enc", "body"], {"file": js["f"], "hash": {"in": uniq}},
                        None, max(1, len(uniq)))),
              ("g", sel("derived", ["part", "body"], {"file": js["f"], "version": js["v"], "kind": "text"},
                        [("part", "asc")], PAGE_FETCH))] + park_ops(job, js), "r-text", job)])


def fetch_text(js):
    """The text view of the asked version, or an answer: `corrupt` when a
    block is missing (as `read`), `no_text` without a text view."""
    content = assemble_blocks(js["hashes"], rows(lg, "b"))
    if content is None:
        answer(js, code="corrupt", message="a block of %s@%s is missing" % (js["f"], v12(js["v"])),
               job=job)
    text = view_text(content, rows(lg, "g"))[0]
    if text is None:
        answer(js, code="no_text", message="%s@%s has no text view" % (js["f"], v12(js["v"])), job=job)
    return text


if phase == "r-text":
    fetch_text(js)
    if not js["indexed"]:
        answer(js, code="not_indexed", message="%s@%s has no embeddings" % (js["f"], v12(js["v"])),
               job=job, extra={"current": v12(js["v"])})
    emit([to_embed(job, [js["q"][:EMBED_MAX_CHARS]])])

if phase == "embedded" and job.startswith("r-"):
    got = incoming()
    vec = got.get("vectors")
    if not isinstance(vec, list) or len(vec) != 1 or not isinstance(vec[0], str):
        answer(js, code="embed_failed", message=str(got.get("error") or "no query vector"), job=job)
    js["qv"], js["qmodel"] = vec[0], str(got.get("model") or "")
    k = js["limit"] if js["op"] == "search" else knob_int("ask_sections", ASK_SECTIONS)
    uniq = sorted(set(js["hashes"]))
    emit([st([("sim", {"operation": "similar", "table": "embeddings",
                       "columns": ["section", "from_line", "to_line", "dim"],
                       "vector_column": "blob", "vector": js["qv"],
                       "where": {"file": js["f"], "version": js["v"], "model": js["qmodel"]},
                       "limit": k}),
              ("b", sel("blocks", ["hash", "enc", "body"], {"file": js["f"], "hash": {"in": uniq}},
                        None, max(1, len(uniq)))),
              ("g", sel("derived", ["part", "body"], {"file": js["f"], "version": js["v"], "kind": "text"},
                        [("part", "asc")], PAGE_FETCH)),
              ("p", sel("pending", ["body"], mine(job)))], "r-hits", job)])

if phase == "r-hits":
    lines = split_lines(fetch_text(js))
    hits = rows(lg, "sim")
    if not hits:
        answer(js, code="not_indexed", job=job,
               message="%s@%s has no embeddings of model %r" % (js["f"], v12(js["v"]), js["qmodel"]),
               extra={"current": v12(js["v"])})
    if js["op"] == "search":
        out = []
        for h in hits:
            a, b = int(h.get("from_line") or 1), int(h.get("to_line") or 1)
            out.append({"section": h.get("section", ""), "from_line": a, "to_line": b,
                        "score": score(h.get("distance"), (h.get("dim") or 0)),
                        "preview": [read_form(n, lines[n - 1])
                                    for n in range(a, min(b, a + PREVIEW_LINES - 1) + 1)
                                    if n <= len(lines)]})
        answer(js, {"file": js["f"], "version": v12(js["v"]), "mode": "semantic", "hits": out}, job=job)
    chunks = sorted({(max(1, int(h.get("from_line") or 1)),
                      min(len(lines), int(h.get("to_line") or 1))) for h in hits})
    extra_hit = exact_hit(js["q"], lines, chunks)
    if extra_hit:
        chunks = sorted(chunks + [extra_hit])
    js["chunks"] = chunks
    text = ask_input(js["path"], v12(js["v"]), js["summary"], chunks, lines, js["q"])
    for k in ("hashes", "qv"):
        js.pop(k, None)
    # The park goes out FIRST: the store takes it before the select the
    # summarizer's answer sends, which cannot leave before the model answered.
    emit([st([("p-upd", upd("pending", {"body": json.dumps(js)}, mine(job)))], "noop", job),
          to_summarizer(job, ASK_PROMPT, text)])

if phase == "summary" and job.startswith("r-"):
    got = incoming()
    if got.get("finish") != "stop" or not str(got.get("text") or "").strip():
        answer(js, code="model_failed", job=job,
               message="the summarizer gave no answer (finish %r, error %r)"
               % (got.get("finish"), got.get("error_code")))
    text, srcs = parse_sources(got["text"], [tuple(c) for c in js.get("chunks") or []])
    answer(js, {"file": js["f"], "version": v12(js["v"]), "answer": text, "sources": srcs}, job=job)

say("job %s: phase %r has no step -- dropped" % (job, phase))
emit([])
